80	func runMigrateCheckpointsV2(ctx context.Context, cmd *cobra.Command, force bool) error {
81		repo, err := strategy.OpenRepository(ctx)
82		if err != nil {
83			cmd.SilenceUsage = true
84			fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run from within a git repository.")
85			return NewSilentError(err)
86		}
87	
88		v1Store := checkpoint.NewGitStore(repo)
89		v2Store := checkpoint.NewV2GitStore(repo, migrateRemoteName)
90		out := cmd.OutOrStdout()
91		progressOut := cmd.ErrOrStderr()
92	
93		result, freshlyPackedRefs, err := migrateCheckpointsV2Internal(ctx, repo, v1Store, v2Store, progressOut, force)
94		if err != nil {
95			return err
96		}
97	
98		// Skip the generation-metadata repair pass on no-op reruns: it does a
99		// `git ls-remote` plus a transcript-blob walk per archived /full/<n>,
100		// minutes on big repos. When we did write archives, freshly-packed refs
101		// are excluded — their generation.json is already correct from
102		// AggregateTranscriptTimestamps in the packer.
103		var repairResult *strategy.RepairV2GenerationMetadataResult
104		if len(freshlyPackedRefs) > 0 {
105			var repairErr error
106			repairResult, repairErr = strategy.RepairV2GenerationMetadata(ctx, freshlyPackedRefs)
107			if repairErr != nil {
108				return fmt.Errorf("failed to repair archived v2 generation metadata: %w", repairErr)
109			}
110			printV2GenerationRepairResult(out, cmd.ErrOrStderr(), repairResult)
111		}
112	
113		printMigrateCompletion(out, result)
114		fmt.Fprintln(out, "Note: V2 checkpoints are stored as custom refs under refs/entire/checkpoints/v2/*, not as a branch visible in the GitHub UI.")
115		fmt.Fprintf(out, "To inspect pushed v2 checkpoint refs locally, run: git ls-remote %s \"refs/entire/checkpoints/v2/*\"\n", migrateRemoteName)
116		fmt.Fprintln(out, `You may also open a checkpoint's details in the Entire web app and click the "session logs" link to view the log files and metadata.`)
117	
118		if result.failed > 0 {
119			return NewSilentError(fmt.Errorf("%d checkpoint(s) failed to migrate", result.failed))
120		}
121		if repairResult != nil && len(repairResult.Failed) > 0 {
122			fmt.Fprintf(out, "%d archived generation(s) failed metadata repair. Check warnings above for details.\n", len(repairResult.Failed))
123			return NewSilentError(fmt.Errorf("%d archived generation(s) failed metadata repair", len(repairResult.Failed)))
124		}
125	
126		return nil
127	}
