131	func printMigrateCompletion(out io.Writer, result *migrateResult) {
132		if result.total == 0 {
133			fmt.Fprintln(out, "Nothing to migrate: no v1 checkpoints found")
134			fmt.Fprintln(out)
135			return
136		}
137	
138		fmt.Fprintf(out, "Migration complete: %d migrated, %d skipped, %d failed\n",
139			result.migrated, result.skipped, result.failed)
140	
141		if result.hasLoggedDetails() {
142			fmt.Fprintf(out, "Details for skipped, missing, incomplete, or failed checkpoints were logged to %s.\n", migrationLogFile)
143		}
144	
145		fmt.Fprintln(out)
146	}
