152	func printV2GenerationRepairResult(out, errOut io.Writer, result *strategy.RepairV2GenerationMetadataResult) {
153		if result == nil {
154			return
155		}
156	
157		for _, warning := range result.Warnings {
158			fmt.Fprintf(errOut, "Warning: %s\n", warning)
159		}
160	
161		if len(result.Repaired) == 0 && len(result.Failed) == 0 {
162			return
163		}
164	
165		fmt.Fprintf(out, "Archived generation metadata repair: %d repaired, %d skipped, %d failed\n",
166			len(result.Repaired), len(result.Skipped), len(result.Failed))
