194	// migrateCheckpointsV2 is the test entry point; it discards the
195	// freshly-packed refs list that production code uses to gate the repair pass.
196	func migrateCheckpointsV2(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, progressOut io.Writer, force bool) (*migrateResult, error) {
197		result, _, err := migrateCheckpointsV2Internal(ctx, repo, v1Store, v2Store, progressOut, force)
198		return result, err
199	}
