201	// migrateCheckpointsV2Internal returns the /full/<n> refs the packer wrote so
202	// the caller can pass them as exclusions to the generation-metadata repair
203	// pass.
204	func migrateCheckpointsV2Internal(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, progressOut io.Writer, force bool) (*migrateResult, []plumbing.ReferenceName, error) {
205		v1List, err := v1Store.ListCommitted(ctx)
206		if err != nil {
207			return nil, nil, fmt.Errorf("failed to list v1 checkpoints: %w", err)
208		}
209	
210		if len(v1List) == 0 {
211			return &migrateResult{}, nil, nil
212		}
213	
214		sortMigratableCheckpoints(v1List)
215		total := len(v1List)
216		result := &migrateResult{total: total}
217		progress := startProgressBar(progressOut, "Migrating checkpoints", total)
218		defer progress.Finish()
219	
220		_, fullCurrentRefErr := repo.Reference(plumbing.ReferenceName(paths.V2FullCurrentRefName), true)
221		fullCurrentExistsBefore := fullCurrentRefErr == nil
222	
223		// One up-front tree walk to make per-session "are /full/* artifacts
224		// present?" checks O(1) inside the migration loop.
225		fullArtifactsIndex, err := v2Store.BuildFullSessionArtifactsIndex()
226		if err != nil {
227			return nil, nil, fmt.Errorf("build v2 /full/* presence index: %w", err)
228		}
229	
230		packer := newGenerationPacker(repo, v2Store)
231	
232		for _, info := range v1List {
233			fullCheckpoint, outcome, migrateErr := migrateOneCheckpoint(ctx, repo, v1Store, v2Store, info, force, fullArtifactsIndex)
234			result.missingSessions += outcome.missingSessions
235			if outcome.compactTranscriptSkipped {
236				result.compactTranscriptSkipped++
237			}
238	
239			if migrateErr != nil {
240				switch {
241				case errors.Is(migrateErr, errAlreadyMigrated):
242					logCheckpointMigrationSkip(ctx, info.CheckpointID, "already in v2", migrateErr)
243					result.skipped++
244				case errors.Is(migrateErr, errNoMigratableSessions):
245					logCheckpointMigrationSkip(ctx, info.CheckpointID, "no migratable v1 sessions", migrateErr)
246					result.skipped++
247				default:
248					logging.Error(ctx, "checkpoint migration failed",
249						slog.String("checkpoint_id", string(info.CheckpointID)),
250						slog.String("error", migrateErr.Error()),
251					)
252					result.failed++
253				}
254				progress.Increment()
255				continue
256			}
257	
258			if fullCheckpoint != nil {
259				if packErr := packer.add(ctx, *fullCheckpoint); packErr != nil {
260					return result, packer.writtenRefs, fmt.Errorf("failed to pack migrated raw transcripts: %w", packErr)
261				}
262			}
263			result.migrated++
264			progress.Increment()
265		}
266	
267		if err := packer.finalize(ctx, !fullCurrentExistsBefore); err != nil {
268			return result, packer.writtenRefs, fmt.Errorf("failed to pack migrated raw transcripts: %w", err)
269		}
270	
271		return result, packer.writtenRefs, nil
272	}
