274	func logCheckpointMigrationSkip(ctx context.Context, checkpointID id.CheckpointID, reason string, err error) {
275		logging.Info(ctx, "checkpoint migration skipped",
276			slog.String("checkpoint_id", string(checkpointID)),
277			slog.String("reason", reason),
278			slog.String("error", err.Error()),
279		)
280	}
