282	func sortMigratableCheckpoints(checkpoints []checkpoint.CommittedInfo) {
283		sort.SliceStable(checkpoints, func(i, j int) bool {
284			left := checkpoints[i].CreatedAt
285			right := checkpoints[j].CreatedAt
286			switch {
287			case left.IsZero() && right.IsZero():
288				return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
289			case left.IsZero():
290				return false
291			case right.IsZero():
292				return true
293			case left.Equal(right):
294				return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
295			default:
296				return left.Before(right)
297			}
298		})
299	}
