301	type migrateCheckpointOutcome struct {
302		missingSessions          int
303		compactTranscriptSkipped bool
304	}
305	
306	func migrateOneCheckpoint(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, force bool, fullArtifacts checkpoint.FullSessionArtifactsIndex) (*migratedFullCheckpoint, migrateCheckpointOutcome, error) {
307		var outcome migrateCheckpointOutcome
308	
309		existing, err := v2Store.ReadCommitted(ctx, info.CheckpointID)
310		if err != nil {
311			return nil, outcome, fmt.Errorf("failed to check v2 for checkpoint %s: %w", info.CheckpointID, err)
312		}
313	
314		if existing != nil && !force {
315			// Already in v2. Pack sessions whose /full/* artifacts are missing
316			// (resume an interrupted run) and backfill transcript.jsonl on /main
317			// where it's missing. With nothing to do on either front, return
318			// errAlreadyMigrated so the caller counts it as skipped.
319			fullCheckpoint, err := collectMissingFullCheckpointForPacking(ctx, repo, v1Store, v2Store, info, existing, fullArtifacts)
320			if err != nil && !errors.Is(err, errAlreadyMigrated) {
321				return nil, outcome, err
322			}
323			backfilled, backfillErr := backfillCompactTranscripts(ctx, v1Store, v2Store, info, existing)
324			if errors.Is(backfillErr, errTranscriptNotGeneratable) {
325				outcome.compactTranscriptSkipped = true
326			} else if backfillErr != nil && !errors.Is(backfillErr, errAlreadyMigrated) {
327				return nil, outcome, backfillErr
328			}
329			if fullCheckpoint == nil {
330				if backfilled > 0 {
331					return nil, outcome, nil
332				}
333				return nil, outcome, errAlreadyMigrated
334			}
335			return fullCheckpoint, outcome, nil
336		}
337	
338		if existing != nil && force {
339			if pruneErr := pruneV2CheckpointForForce(ctx, repo, v2Store, info.CheckpointID); pruneErr != nil {
340				return nil, outcome, fmt.Errorf("failed to reset existing v2 checkpoint %s before force migration: %w", info.CheckpointID, pruneErr)
341			}
342		}
343	
344		summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
345		if err != nil {
346			return nil, outcome, fmt.Errorf("failed to read v1 summary: %w", err)
347		}
348		if summary == nil {
349			return nil, outcome, fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
350		}
351	
352		compactFailed := false
353		shouldCopyTaskMetadata := false
354		skippedMissingSessions := 0
355		migratedSessions := 0
356		v1ToV2SessionIdx := make(map[int]int, len(summary.Sessions))
357		fullCheckpoint := &migratedFullCheckpoint{
358			checkpointID: info.CheckpointID,
359		}
360	
361		for sessionIdx := range len(summary.Sessions) {
362			content, skipped, readErr := readV1SessionForMigration(ctx, v1Store, info.CheckpointID, sessionIdx)
363			if skipped {
364				skippedMissingSessions++
365				outcome.missingSessions++
366				continue
367			}
368			if readErr != nil {
369				return nil, outcome, fmt.Errorf("failed to read v1 session %d: %w", sessionIdx, readErr)
370			}
371			if content.Metadata.IsTask {
372				shouldCopyTaskMetadata = true
373			}
374	
375			opts := buildMigrateWriteOpts(content, info, summary.CombinedAttribution)
376	
377			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
378			if compacted != nil {
379				opts.CompactTranscript = compacted
380				opts.CompactTranscriptStart = computeCompactOffset(ctx, content.Transcript, compacted, content.Metadata)
381			} else if len(content.Transcript) > 0 {
382				compactFailed = true
383			}
384	
385			mainOpts := opts
386			mainOpts.Transcript = redact.AlreadyRedacted(nil)
387			v2SessionIdx, writeErr := v2Store.WriteCommittedWithSessionIndex(ctx, mainOpts)
388			if writeErr != nil {
389				return nil, outcome, fmt.Errorf("failed to write v2 session %d: %w", sessionIdx, writeErr)
390			}
391			v1ToV2SessionIdx[sessionIdx] = v2SessionIdx
392			fullCheckpoint.sessions = append(fullCheckpoint.sessions, migratedFullSession{
393				sessionIndex: v2SessionIdx,
394				content:      content,
395			})
396			migratedSessions++
397		}
398	
399		if migratedSessions == 0 {
400			return nil, outcome, fmt.Errorf("%w: v1 metadata lists %d session(s), but no transcript/session content exists for any of them", errNoMigratableSessions, len(summary.Sessions))
401		}
402	
403		if shouldCopyTaskMetadata {
404			taskTrees, taskErr := collectTaskMetadataForMigratedFullGeneration(repo, info.CheckpointID, summary, v1ToV2SessionIdx)
405			if taskErr != nil {
406				logging.Warn(ctx, "failed to copy task metadata to v2",
407					slog.String("checkpoint_id", string(info.CheckpointID)),
408					slog.String("error", taskErr.Error()),
409				)
410			} else {
411				fullCheckpoint.taskTrees = taskTrees
412			}
413		}
414	
415		if compactFailed {
416			outcome.compactTranscriptSkipped = true
417			logging.Warn(ctx, "compact transcript not generated during checkpoint migration",
418				slog.String("checkpoint_id", string(info.CheckpointID)),
419				slog.Int("migrated_sessions", migratedSessions),
420			)
421		}
422		if skippedMissingSessions > 0 {
423			logging.Warn(ctx, "checkpoint migration skipped v1 sessions with missing transcript/session content",
424				slog.String("checkpoint_id", string(info.CheckpointID)),
425				slog.Int("missing_sessions", skippedMissingSessions),
426			)
427		}
428	
429		return fullCheckpoint, outcome, nil
430	}
