432	// generationPacker buffers up to batchSize migrated checkpoints and flushes
433	// them into a single archived /full/<n> ref each time the buffer fills, so
434	// peak heap stays bounded by one batch worth of transcripts instead of
435	// growing with the total v1 list. The next generation number is resolved
436	// lazily on first flush so force-migration prune steps that remove existing
437	// archived refs are visible before we pick the next slot.
438	type generationPacker struct {
439		repo           *git.Repository
440		v2Store        *checkpoint.V2GitStore
441		batchSize      int
442		nextGeneration int
443		numbered       bool
444		pending        []migratedFullCheckpoint
445		flushed        bool
446		// writtenRefs records every /full/<n> ref this packer creates so the
447		// caller can exclude them from the generation-metadata repair pass.
448		writtenRefs []plumbing.ReferenceName
449	}
450	
451	func newGenerationPacker(repo *git.Repository, v2Store *checkpoint.V2GitStore) *generationPacker {
452		batchSize := migrateMaxCheckpointsPerGeneration
453		if batchSize <= 0 {
454			batchSize = checkpoint.DefaultMaxCheckpointsPerGeneration
455		}
456		return &generationPacker{
457			repo:      repo,
458			v2Store:   v2Store,
459			batchSize: batchSize,
460		}
461	}
462	
463	func (p *generationPacker) add(ctx context.Context, cp migratedFullCheckpoint) error {
464		p.pending = append(p.pending, cp)
465		if len(p.pending) >= p.batchSize {
466			return p.flush(ctx)
467		}
468		return nil
469	}
470	
471	func (p *generationPacker) flush(ctx context.Context) error {
472		if len(p.pending) == 0 {
473			return nil
474		}
475		if !p.numbered {
476			next, err := p.v2Store.NextGenerationNumber()
477			if err != nil {
478				return fmt.Errorf("list archived v2 generations: %w", err)
479			}
480			p.nextGeneration = next
481			p.numbered = true
482		}
483		refName := plumbing.ReferenceName(fmt.Sprintf("%s%013d", paths.V2FullRefPrefix, p.nextGeneration))
484		if err := writeMigratedFullGeneration(ctx, p.repo, refName, p.pending); err != nil {
485			return err
486		}
487		p.writtenRefs = append(p.writtenRefs, refName)
488		p.nextGeneration++
489		p.pending = nil
490		p.flushed = true
491		return nil
492	}
493	
494	func (p *generationPacker) finalize(ctx context.Context, ensureEmptyCurrent bool) error {
495		if err := p.flush(ctx); err != nil {
496			return err
497		}
498		if p.flushed && ensureEmptyCurrent {
499			return ensureEmptyV2FullCurrent(ctx, p.repo)
500		}
501		return nil
502	}
503	
504	func writeMigratedFullGeneration(ctx context.Context, repo *git.Repository, refName plumbing.ReferenceName, checkpoints []migratedFullCheckpoint) error {
505		entries := make(map[string]object.TreeEntry)
506	
507		for _, cp := range checkpoints {
508			for _, session := range cp.sessions {
509				if err := writeMigratedFullSessionEntries(ctx, repo, cp, session, entries); err != nil {
510					return fmt.Errorf("write full session entries for checkpoint %s session %d: %w", cp.checkpointID, session.sessionIndex, err)
511				}
512			}
513		}
514	
515		treeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
516		if err != nil {
517			return fmt.Errorf("build migrated generation tree: %w", err)
518		}
519	
520		v2Store := checkpoint.NewV2GitStore(repo, migrateRemoteName)
521		// Reuse the transcripts already in memory rather than walking the tree
522		// we just built — same first/last-event range, no redundant blob reads.
523		gen, found := checkpoint.AggregateTranscriptTimestamps(migratedTranscripts(checkpoints))
524		if !found {
525			var err error
526			gen, found, err = v2Store.ComputeGenerationCheckpointTimestamps(treeHash)
527			if err != nil {
528				return fmt.Errorf("compute checkpoint timestamps: %w", err)
529			}
530		}
531		if !found {
532			gen, found = generationMetadataFromMigratedSessions(checkpoints)
533		}
534		if !found {
535			return fmt.Errorf("no timestamps found for migrated generation %s", refName)
536		}
537	
538		treeHash, err = v2Store.AddGenerationJSONToTree(treeHash, gen)
539		if err != nil {
540			return fmt.Errorf("add generation metadata: %w", err)
541		}
542	
543		commitHash, err := checkpoint.CreateCommit(ctx, repo, treeHash, plumbing.ZeroHash,
544			fmt.Sprintf("Archive migrated generation: %s\n", refName),
545			migrateAuthorName, migrateAuthorEmail)
546		if err != nil {
547			return fmt.Errorf("create migrated generation commit: %w", err)
548		}
549	
550		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
551			return fmt.Errorf("update migrated generation ref %s: %w", refName, err)
552		}
553		return nil
554	}
