556	func migratedTranscripts(checkpoints []migratedFullCheckpoint) [][]byte {
557		var transcripts [][]byte
558		for _, cp := range checkpoints {
559			for _, session := range cp.sessions {
560				if len(session.content.Transcript) == 0 {
561					continue
562				}
563				transcripts = append(transcripts, session.content.Transcript)
564			}
565		}
566		return transcripts
567	}
