569	func generationMetadataFromMigratedSessions(checkpoints []migratedFullCheckpoint) (checkpoint.GenerationMetadata, bool) {
570		var gen checkpoint.GenerationMetadata
571		found := false
572		for _, cp := range checkpoints {
573			for _, session := range cp.sessions {
574				checkpoint.MergeGenerationTime(&gen, &found, session.content.Metadata.CreatedAt)
575			}
576		}
577		return gen, found
578	}
