580	func writeMigratedFullSessionEntries(ctx context.Context, repo *git.Repository, cp migratedFullCheckpoint, session migratedFullSession, entries map[string]object.TreeEntry) error {
581		sessionPath := fmt.Sprintf("%s/%d/", cp.checkpointID.Path(), session.sessionIndex)
582		transcript := session.content.Transcript
583	
584		chunks, err := agent.ChunkTranscript(ctx, transcript, session.content.Metadata.Agent)
585		if err != nil {
586			return fmt.Errorf("chunk transcript: %w", err)
587		}
588		for i, chunk := range chunks {
589			blobHash, blobErr := checkpoint.CreateBlobFromContent(repo, chunk)
590			if blobErr != nil {
591				return fmt.Errorf("create transcript blob: %w", blobErr)
592			}
593			path := sessionPath + agent.ChunkFileName(paths.V2RawTranscriptFileName, i)
594			entries[path] = object.TreeEntry{
595				Name: path,
596				Mode: filemode.Regular,
597				Hash: blobHash,
598			}
599		}
600	
601		hashPath := sessionPath + paths.V2RawTranscriptHashFileName
602		contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
603		hashBlob, err := checkpoint.CreateBlobFromContent(repo, []byte(contentHash))
604		if err != nil {
605			return fmt.Errorf("create transcript hash blob: %w", err)
606		}
607		entries[hashPath] = object.TreeEntry{
608			Name: hashPath,
609			Mode: filemode.Regular,
610			Hash: hashBlob,
611		}
612	
613		for _, taskTreeHash := range cp.taskTrees[session.sessionIndex] {
614			taskTree, treeErr := repo.TreeObject(taskTreeHash)
615			if treeErr != nil {
616				return fmt.Errorf("read task metadata tree: %w", treeErr)
617			}
618			taskEntries := make(map[string]object.TreeEntry)
619			if flattenErr := checkpoint.FlattenTree(repo, taskTree, sessionPath+"tasks", taskEntries); flattenErr != nil {
620				return fmt.Errorf("flatten task metadata tree: %w", flattenErr)
621			}
622			for path, entry := range taskEntries {
623				if _, exists := entries[path]; exists {
624					continue
625				}
626				entries[path] = entry
627			}
628		}
629	
630		return nil
631	}
