677	func pruneV2CheckpointForForce(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID) error {
678		for _, refName := range []plumbing.ReferenceName{
679			plumbing.ReferenceName(paths.V2MainRefName),
680			plumbing.ReferenceName(paths.V2FullCurrentRefName),
681		} {
682			if err := pruneV2CheckpointRef(ctx, repo, v2Store, refName, cpID); err != nil {
