701	func pruneV2CheckpointRef(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, refName plumbing.ReferenceName, cpID id.CheckpointID) error {
702		parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
703		if err != nil {
704			if errors.Is(err, plumbing.ErrReferenceNotFound) {
705				return nil
706			}
707			return fmt.Errorf("failed to get v2 ref state for %s: %w", refName, err)
708		}
709	
710		rootTree, err := repo.TreeObject(rootTreeHash)
711		if err != nil {
712			return fmt.Errorf("failed to read v2 tree for %s: %w", refName, err)
713		}
714		if _, err := rootTree.Tree(cpID.Path()); err != nil {
715			return nil //nolint:nilerr // Checkpoint is absent from this ref, so there is nothing to prune.
716		}
717	
718		shardPrefix := string(cpID[:2])
719		shardSuffix := string(cpID[2:])
720		newRoot, err := pruneCheckpointFromRoot(repo, rootTreeHash, shardPrefix, shardSuffix)
721		if err != nil {
722			return fmt.Errorf("failed to remove checkpoint subtree from %s: %w", refName, err)
723		}
724		if newRoot == rootTreeHash {
725			return nil
726		}
727	
728		commitHash, err := checkpoint.CreateCommit(ctx, repo, newRoot, parentHash,
729			fmt.Sprintf("Reset checkpoint before force migration: %s\n", cpID),
730			migrateAuthorName, migrateAuthorEmail)
731		if err != nil {
732			return fmt.Errorf("failed to create v2 prune commit for %s: %w", refName, err)
733		}
734	
735		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
736			return fmt.Errorf("failed to update ref %s: %w", refName, err)
737		}
738		return nil
739	}
740	
741	func pruneV2ArchivedCheckpointRef(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, refName plumbing.ReferenceName, cpID id.CheckpointID) error {
742		parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
743		if err != nil {
744			if errors.Is(err, plumbing.ErrReferenceNotFound) {
745				return nil
746			}
747			return fmt.Errorf("failed to get v2 ref state for %s: %w", refName, err)
748		}
749	
750		rootTree, err := repo.TreeObject(rootTreeHash)
751		if err != nil {
752			return fmt.Errorf("failed to read v2 tree for %s: %w", refName, err)
753		}
754		if _, err := rootTree.Tree(cpID.Path()); err != nil {
755			return nil //nolint:nilerr // Checkpoint is absent from this ref, so there is nothing to prune.
756		}
757	
758		shardPrefix := string(cpID[:2])
759		shardSuffix := string(cpID[2:])
760		newRoot, err := pruneCheckpointFromRoot(repo, rootTreeHash, shardPrefix, shardSuffix)
761		if err != nil {
762			return fmt.Errorf("failed to remove checkpoint subtree from %s: %w", refName, err)
763		}
764		if newRoot == rootTreeHash {
765			return nil
766		}
767	
768		count, err := v2Store.CountCheckpointsInTree(newRoot)
769		if err != nil {
770			return fmt.Errorf("failed to count checkpoints in pruned %s: %w", refName, err)
771		}
772		if count == 0 {
773			if err := repo.Storer.RemoveReference(refName); err != nil {
774				return fmt.Errorf("failed to remove empty archived v2 generation %s: %w", refName, err)
775			}
776			return nil
777		}
778	
779		newRoot, err = addRecomputedGenerationJSON(v2Store, newRoot)
780		if err != nil {
781			return fmt.Errorf("failed to recompute generation metadata for %s: %w", refName, err)
782		}
783	
784		commitHash, err := checkpoint.CreateCommit(ctx, repo, newRoot, parentHash,
785			fmt.Sprintf("Reset checkpoint before force migration: %s\n", cpID),
786			migrateAuthorName, migrateAuthorEmail)
787		if err != nil {
788			return fmt.Errorf("failed to create v2 prune commit for %s: %w", refName, err)
789		}
790	
791		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
792			return fmt.Errorf("failed to update ref %s: %w", refName, err)
793		}
794		return nil
795	}
