797	func addRecomputedGenerationJSON(v2Store *checkpoint.V2GitStore, treeHash plumbing.Hash) (plumbing.Hash, error) {
798		gen, found, err := v2Store.ComputeGenerationTimestampsFromTrees(treeHash, nil)
799		if err != nil {
800			return plumbing.ZeroHash, fmt.Errorf("compute raw transcript timestamps: %w", err)
801		}
802		if !found {
803			gen, found, err = v2Store.ComputeGenerationCheckpointTimestamps(treeHash)
804			if err != nil {
805				return plumbing.ZeroHash, fmt.Errorf("compute checkpoint timestamps: %w", err)
806			}
807		}
808		if !found {
809			return treeHash, nil
810		}
811	
812		newTreeHash, err := v2Store.AddGenerationJSONToTree(treeHash, gen)
813		if err != nil {
814			return plumbing.ZeroHash, fmt.Errorf("add generation metadata: %w", err)
815		}
816		return newTreeHash, nil
817	}
