819	func pruneCheckpointFromRoot(repo *git.Repository, rootTreeHash plumbing.Hash, shardPrefix, shardSuffix string) (plumbing.Hash, error) {
820		newRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
821			[]string{shardPrefix},
822			nil,
823			checkpoint.UpdateSubtreeOptions{
824				MergeMode:   checkpoint.MergeKeepExisting,
825				DeleteNames: []string{shardSuffix},
826			},
827		)
828		if err != nil {
829			return plumbing.ZeroHash, fmt.Errorf("failed to prune checkpoint from shard: %w", err)
830		}
831		if newRoot == rootTreeHash {
832			return newRoot, nil
833		}
834	
835		newRootTree, err := repo.TreeObject(newRoot)
836		if err != nil {
837			return plumbing.ZeroHash, fmt.Errorf("failed to read pruned root tree: %w", err)
838		}
839		shardTree, err := newRootTree.Tree(shardPrefix)
840		if err != nil {
841			return newRoot, nil //nolint:nilerr // The shard prefix was already absent after pruning.
842		}
843		if len(shardTree.Entries) > 0 {
844			return newRoot, nil
845		}
846	
847		prunedRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
848			nil,
849			nil,
850			checkpoint.UpdateSubtreeOptions{
851				MergeMode:   checkpoint.MergeKeepExisting,
852				DeleteNames: []string{shardPrefix},
853			},
854		)
855		if err != nil {
856			return plumbing.ZeroHash, fmt.Errorf("failed to prune empty shard prefix: %w", err)
857		}
858		return prunedRoot, nil
859	}
