900	func compactTranscriptForStartLine(ctx context.Context, transcript []byte, m checkpoint.CommittedMetadata, startLine int) []byte {
901		if len(transcript) == 0 {
902			return nil
903		}
904		if m.Agent == "" {
905			logging.Warn(ctx, "compact transcript skipped: no agent type in checkpoint metadata",
906				slog.String("checkpoint_id", string(m.CheckpointID)),
907			)
908			return nil
909		}
910	
911		compacted, err := compact.Compact(redact.AlreadyRedacted(transcript), compact.MetadataFields{
912			Agent:      string(m.Agent),
913			CLIVersion: versioninfo.Version,
914			StartLine:  startLine,
915		})
916		if err != nil {
917			logging.Warn(ctx, "compact transcript generation failed during migration",
918				slog.String("checkpoint_id", string(m.CheckpointID)),
919				slog.String("agent", string(m.Agent)),
920				slog.String("error", err.Error()),
921			)
922			return nil
923		}
924		if len(compacted) == 0 {
925			logging.Warn(ctx, "transcript.jsonl generation produced no output",
926				slog.String("checkpoint_id", string(m.CheckpointID)),
927				slog.String("agent", string(m.Agent)),
928				slog.Int("input_bytes", len(transcript)),
929			)
930			return nil
931		}
932		return compacted
933	}
934	
935	// computeCompactOffset determines the transcript.jsonl line offset for a checkpoint
936	// by comparing a full compact (startLine=0) against the scoped compact. The difference
937	// is the number of compact lines before this checkpoint's data.
938	func computeCompactOffset(ctx context.Context, fullTranscript, fullCompact []byte, m checkpoint.CommittedMetadata) int {
939		startLine := m.GetTranscriptStart()
940		if startLine == 0 || len(fullTranscript) == 0 || m.Agent == "" {
941			return 0
942		}
943	
944		if len(fullCompact) == 0 {
945			return 0
946		}
947	
948		scopedCompact, err := compact.Compact(redact.AlreadyRedacted(fullTranscript), compact.MetadataFields{
949			Agent:      string(m.Agent),
950			CLIVersion: versioninfo.Version,
951			StartLine:  startLine,
952		})
953		if err != nil {
954			logging.Warn(ctx, "compact transcript offset calculation failed during migration",
955				slog.String("checkpoint_id", string(m.CheckpointID)),
956				slog.String("agent", string(m.Agent)),
957				slog.String("error", err.Error()),
958			)
959			return 0
960		}
961		if len(scopedCompact) == 0 {
962			return 0
963		}
964	
965		fullLines := bytes.Count(fullCompact, []byte{'\n'})
966		scopedLines := bytes.Count(scopedCompact, []byte{'\n'})
967		offset := fullLines - scopedLines
968		if offset < 0 {
969			logging.Warn(ctx, "compact transcript offset was negative during migration, defaulting to 0",
970				slog.String("checkpoint_id", string(m.CheckpointID)),
971				slog.Int("full_lines", fullLines),
972				slog.Int("scoped_lines", scopedLines),
973			)
974			return 0
975		}
976		return offset
977	}
