979	func collectTaskMetadataForMigratedFullGeneration(repo *git.Repository, cpID id.CheckpointID, summary *checkpoint.CheckpointSummary, v1ToV2SessionIdx map[int]int) (map[int][]plumbing.Hash, error) {
980		rootTaskV2SessionIdx, attachRootTasks := latestMigratedV2SessionIndex(v1ToV2SessionIdx)
981		return collectTaskMetadataForMigratedFullGenerationWithRootSession(repo, cpID, summary, v1ToV2SessionIdx, rootTaskV2SessionIdx, attachRootTasks)
982	}
983	
984	func collectTaskMetadataForMigratedFullGenerationWithRootSession(
985		repo *git.Repository,
986		cpID id.CheckpointID,
987		summary *checkpoint.CheckpointSummary,
988		v1ToV2SessionIdx map[int]int,
989		rootTaskV2SessionIdx int,
990		attachRootTasks bool,
991	) (map[int][]plumbing.Hash, error) {
992		v1Tree, err := resolveV1CheckpointTree(repo, cpID)
993		if err != nil {
994			return nil, err
995		}
996	
997		taskTrees := make(map[int][]plumbing.Hash)
998	
999		// Legacy v1 layout stores task metadata at checkpoint root: <cp>/tasks/<tool-use-id>/...
1000		// Prefer attaching this tree to the latest session in v2.
1001		if rootTasksTree, rootTasksErr := v1Tree.Tree("tasks"); rootTasksErr == nil {
1002			if attachRootTasks {
1003				taskTrees[rootTaskV2SessionIdx] = append(taskTrees[rootTaskV2SessionIdx], rootTasksTree.Hash)
1004			}
1005		}
1006	
1007		for sessionIdx := range len(summary.Sessions) {
1008			sessionDir := strconv.Itoa(sessionIdx)
1009			sessionTree, sessionErr := v1Tree.Tree(sessionDir)
1010			if sessionErr != nil {
1011				continue
1012			}
1013	
1014			tasksTree, tasksErr := sessionTree.Tree("tasks")
1015			if tasksErr != nil {
1016				continue
1017			}
1018	
1019			v2SessionIdx, ok := v1ToV2SessionIdx[sessionIdx]
1020			if !ok {
1021				continue
1022			}
1023			taskTrees[v2SessionIdx] = append(taskTrees[v2SessionIdx], tasksTree.Hash)
1024		}
1025	
1026		return taskTrees, nil
1027	}
1028	
1029	func latestMigratedV2SessionIndex(v1ToV2SessionIdx map[int]int) (int, bool) {
1030		latest := -1
1031		for _, v2SessionIdx := range v1ToV2SessionIdx {
1032			if v2SessionIdx > latest {
1033				latest = v2SessionIdx
1034			}
1035		}
1036		if latest < 0 {
1037			return -1, false
1038		}
1039		return latest, true
1040	}
1041	
1042	func resolveV1CheckpointTree(repo *git.Repository, cpID id.CheckpointID) (*object.Tree, error) {
1043		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1044		ref, err := repo.Reference(refName, true)
1045		if err != nil {
1046			// Try remote tracking branch
1047			remoteRefName := plumbing.NewRemoteReferenceName(migrateRemoteName, paths.MetadataBranchName)
1048			ref, err = repo.Reference(remoteRefName, true)
1049			if err != nil {
1050				return nil, fmt.Errorf("v1 branch not found: %w", err)
1051			}
1052		}
1053	
1054		commit, err := repo.CommitObject(ref.Hash())
1055		if err != nil {
1056			return nil, fmt.Errorf("failed to get v1 commit: %w", err)
1057		}
1058	
1059		rootTree, err := commit.Tree()
1060		if err != nil {
1061			return nil, fmt.Errorf("failed to get v1 tree: %w", err)
1062		}
1063	
1064		cpTree, err := rootTree.Tree(cpID.Path())
1065		if err != nil {
1066			return nil, fmt.Errorf("checkpoint %s not found in v1 tree: %w", cpID, err)
1067		}
1068	
1069		return cpTree, nil
1070	}
1071	
1072	// collectMissingFullCheckpointForPacking returns a migratedFullCheckpoint
1073	// scoped to the sessions that lack /full/* artifacts on this v2 checkpoint,
1074	// reading their content from v1 so the caller can hand it to the same
1075	// generationPacker fresh migrations use. Returns errAlreadyMigrated when
1076	// every session is already packed.
1077	func collectMissingFullCheckpointForPacking(
1078		ctx context.Context,
1079		repo *git.Repository,
1080		v1Store *checkpoint.GitStore,
1081		v2Store *checkpoint.V2GitStore,
1082		info checkpoint.CommittedInfo,
1083		v2Summary *checkpoint.CheckpointSummary,
1084		fullArtifacts checkpoint.FullSessionArtifactsIndex,
1085	) (*migratedFullCheckpoint, error) {
1086		missingSessions, err := collectMissingFullSessionsForPacking(ctx, v2Store, info.CheckpointID, v2Summary, fullArtifacts)
1087		if err != nil {
1088			return nil, err
1089		}
1090		if len(missingSessions) == 0 {
1091			return nil, errAlreadyMigrated
1092		}
1093	
1094		v1Summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
1095		if err != nil {
1096			return nil, fmt.Errorf("failed to read v1 summary while resuming v2 migration: %w", err)
1097		}
1098		if v1Summary == nil {
1099			return nil, fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
1100		}
1101	
1102		v1BySessionID, err := collectV1SessionIndexesForPacking(ctx, v1Store, info.CheckpointID, v1Summary, missingSessions)
1103		if err != nil {
1104			return nil, err
1105		}
1106	
1107		fullCheckpoint := &migratedFullCheckpoint{
1108			checkpointID: info.CheckpointID,
1109		}
1110		v1ToV2SessionIdx := make(map[int]int)
1111	
1112		for _, missingSession := range missingSessions {
1113			v1Session, ok, readErr := readV1SessionForMissingFullArtifact(ctx, v1Store, info.CheckpointID, v1Summary, v1BySessionID, missingSession)
1114			if readErr != nil {
1115				return nil, readErr
1116			}
1117			if !ok {
1118				return nil, fmt.Errorf("failed to find v1 session for v2 session %d while resuming migration", missingSession.sessionIndex)
1119			}
1120	
1121			fullCheckpoint.sessions = append(fullCheckpoint.sessions, migratedFullSession{
1122				sessionIndex: missingSession.sessionIndex,
1123				content:      v1Session.content,
1124			})
1125			v1ToV2SessionIdx[v1Session.sessionIndex] = missingSession.sessionIndex
1126		}
1127	
1128		latestV2SessionIdx := len(v2Summary.Sessions) - 1
1129		taskTrees, taskErr := collectTaskMetadataForMigratedFullGenerationWithRootSession(
1130			repo,
1131			info.CheckpointID,
1132			v1Summary,
1133			v1ToV2SessionIdx,
1134			latestV2SessionIdx,
1135			latestV2SessionIdx >= 0,
1136		)
1137		if taskErr != nil {
1138			return nil, fmt.Errorf("failed to collect task metadata while resuming migration: %w", taskErr)
1139		}
1140		fullCheckpoint.taskTrees = taskTrees
1141	
1142		return fullCheckpoint, nil
1143	}
