1145	type missingFullSessionForPacking struct {
1146		sessionIndex int
1147		sessionID    string
1148	}
1149	
1150	type v1SessionForPacking struct {
1151		sessionIndex int
1152		content      *checkpoint.SessionContent
1153	}
