1155	func collectMissingFullSessionsForPacking(
1156		ctx context.Context,
1157		v2Store *checkpoint.V2GitStore,
1158		checkpointID id.CheckpointID,
1159		summary *checkpoint.CheckpointSummary,
1160		fullArtifacts checkpoint.FullSessionArtifactsIndex,
1161	) ([]missingFullSessionForPacking, error) {
1162		missingSessions := make([]missingFullSessionForPacking, 0)
1163		for sessionIdx := range len(summary.Sessions) {
1164			// Production passes a pre-built index; nil falls back to the per-call
1165			// predicate for tests that exercise this helper directly.
1166			var ok bool
1167			if fullArtifacts != nil {
1168				ok = fullArtifacts.Has(checkpointID, sessionIdx)
1169			} else {
1170				var checkErr error
1171				ok, checkErr = v2Store.HasFullSessionArtifacts(checkpointID, sessionIdx)
1172				if checkErr != nil {
1173					return nil, fmt.Errorf("failed to check v2 session %d artifacts: %w", sessionIdx, checkErr)
1174				}
1175			}
1176			if ok {
1177				continue
1178			}
1179	
1180			// Metadata-only read: only SessionID is needed downstream.
1181			meta, readErr := v2Store.ReadSessionMetadata(ctx, checkpointID, sessionIdx)
1182			if readErr != nil {
1183				return nil, fmt.Errorf("failed to read v2 session %d metadata while resuming migration: %w", sessionIdx, readErr)
1184			}
1185	
1186			missingSessions = append(missingSessions, missingFullSessionForPacking{
1187				sessionIndex: sessionIdx,
1188				sessionID:    meta.SessionID,
1189			})
1190		}
1191	
1192		return missingSessions, nil
1193	}
