1195	// collectV1SessionIndexesForPacking maps each missing session's id to its v1
1196	// session index. Resolving by session_id is necessary because v1/v2 indices
1197	// can drift — v1 sessions without a transcript are skipped on fresh migration.
1198	func collectV1SessionIndexesForPacking(
1199		ctx context.Context,
1200		v1Store *checkpoint.GitStore,
1201		checkpointID id.CheckpointID,
1202		summary *checkpoint.CheckpointSummary,
1203		missingSessions []missingFullSessionForPacking,
1204	) (map[string][]int, error) {
1205		neededSessionIDs := make(map[string]struct{})
1206		for _, session := range missingSessions {
1207			if session.sessionID != "" {
1208				neededSessionIDs[session.sessionID] = struct{}{}
1209			}
1210		}
1211	
1212		bySessionID := make(map[string][]int)
1213		if len(neededSessionIDs) == 0 {
1214			return bySessionID, nil
1215		}
1216	
1217		for sessionIdx := range len(summary.Sessions) {
1218			metadata, err := v1Store.ReadSessionMetadata(ctx, checkpointID, sessionIdx)
1219			if err != nil {
1220				if ctxErr := ctx.Err(); ctxErr != nil {
1221					return nil, fmt.Errorf("context canceled while reading v1 session metadata: %w", ctxErr)
1222				}
1223				continue
1224			}
1225			if _, ok := neededSessionIDs[metadata.SessionID]; ok {
1226				bySessionID[metadata.SessionID] = append(bySessionID[metadata.SessionID], sessionIdx)
1227			}
1228		}
1229	
1230		return bySessionID, nil
1231	}
1232	
1233	func readV1SessionForMissingFullArtifact(
1234		ctx context.Context,
1235		v1Store *checkpoint.GitStore,
1236		checkpointID id.CheckpointID,
1237		summary *checkpoint.CheckpointSummary,
1238		bySessionID map[string][]int,
1239		missingSession missingFullSessionForPacking,
1240	) (v1SessionForPacking, bool, error) {
1241		var triedSessionIndexes map[int]struct{}
1242		if missingSession.sessionID != "" {
1243			indexes := bySessionID[missingSession.sessionID]
1244			triedSessionIndexes = make(map[int]struct{}, len(indexes))
1245			for i := len(indexes) - 1; i >= 0; i-- {
1246				sessionIdx := indexes[i]
1247				triedSessionIndexes[sessionIdx] = struct{}{}
1248				session, found, err := readV1SessionForPacking(ctx, v1Store, checkpointID, sessionIdx)
1249				if err != nil || found {
1250					return session, found, err
1251				}
1252			}
1253		}
1254	
1255		if missingSession.sessionIndex >= len(summary.Sessions) {
1256			return v1SessionForPacking{}, false, nil
1257		}
1258		if _, tried := triedSessionIndexes[missingSession.sessionIndex]; tried {
1259			return v1SessionForPacking{}, false, nil
1260		}
1261		return readV1SessionForPacking(ctx, v1Store, checkpointID, missingSession.sessionIndex)
1262	}
