1264	func readV1SessionForPacking(
1265		ctx context.Context,
1266		v1Store *checkpoint.GitStore,
1267		checkpointID id.CheckpointID,
1268		sessionIdx int,
1269	) (v1SessionForPacking, bool, error) {
1270		content, err := v1Store.ReadSessionContent(ctx, checkpointID, sessionIdx)
1271		if err != nil {
1272			if errors.Is(err, checkpoint.ErrNoTranscript) || errors.Is(err, checkpoint.ErrCheckpointNotFound) {
1273				return v1SessionForPacking{}, false, nil
1274			}
1275			return v1SessionForPacking{}, false, fmt.Errorf("failed to read v1 session %d while resuming migration: %w", sessionIdx, err)
1276		}
1277	
1278		return v1SessionForPacking{
1279			sessionIndex: sessionIdx,
1280			content:      content,
1281		}, true, nil
1282	}
