1284	func backfillCompactTranscripts(ctx context.Context, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, v2Summary *checkpoint.CheckpointSummary) (int, error) {
1285		missingSessions, skippedNoAgent, err := collectMissingCompactSessionsForBackfill(ctx, v2Store, info.CheckpointID, v2Summary)
1286		if err != nil {
1287			return 0, err
1288		}
1289		if len(missingSessions) == 0 {
1290			if skippedNoAgent {
1291				return 0, fmt.Errorf("%w: no agent type in metadata", errTranscriptNotGeneratable)
1292			}
1293			return 0, errAlreadyMigrated
1294		}
1295	
1296		v1Summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
1297		if err != nil {
1298			return 0, fmt.Errorf("failed to read v1 summary while backfilling compact transcripts: %w", err)
1299		}
1300		if v1Summary == nil {
1301			return 0, fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
1302		}
1303	
1304		v1BySessionID, err := collectV1SessionIndexesForPacking(ctx, v1Store, info.CheckpointID, v1Summary, missingSessions)
1305		if err != nil {
1306			return 0, err
1307		}
1308	
1309		backfilled := 0
1310		skippedBackfill := false
1311		var lastAgent string
1312		for _, missingSession := range missingSessions {
1313			v1Session, ok, readErr := readV1SessionForMissingFullArtifact(ctx, v1Store, info.CheckpointID, v1Summary, v1BySessionID, missingSession)
1314			if readErr != nil {
1315				logging.Warn(ctx, "transcript.jsonl backfill: could not read v1 session",
1316					slog.String("checkpoint_id", string(info.CheckpointID)),
1317					slog.Int("session_index", missingSession.sessionIndex),
1318					slog.String("error", readErr.Error()),
1319				)
1320				skippedBackfill = true
1321				continue
1322			}
1323			if !ok {
1324				logging.Warn(ctx, "transcript.jsonl backfill: no matching v1 session",
1325					slog.String("checkpoint_id", string(info.CheckpointID)),
1326					slog.Int("session_index", missingSession.sessionIndex),
1327				)
1328				skippedBackfill = true
1329				continue
1330			}
1331	
1332			content := v1Session.content
1333			if content.Metadata.Agent != "" {
1334				lastAgent = string(content.Metadata.Agent)
1335			}
1336	
1337			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
1338			if compacted == nil {
1339				if len(content.Transcript) == 0 {
1340					logging.Warn(ctx, "transcript.jsonl backfill: empty transcript in v1",
1341						slog.String("checkpoint_id", string(info.CheckpointID)),
1342						slog.Int("session_index", missingSession.sessionIndex),
1343					)
1344				}
1345				skippedBackfill = true
1346				continue
1347			}
1348	
1349			updateErr := v2Store.UpdateCommitted(ctx, checkpoint.UpdateCommittedOptions{
1350				CheckpointID:      info.CheckpointID,
1351				SessionID:         content.Metadata.SessionID,
1352				CompactTranscript: compacted,
1353			})
1354			if updateErr != nil {
1355				logging.Warn(ctx, "transcript.jsonl backfill: failed to write to v2",
1356					slog.String("checkpoint_id", string(info.CheckpointID)),
1357					slog.Int("session_index", missingSession.sessionIndex),
1358					slog.String("error", updateErr.Error()),
1359				)
1360				skippedBackfill = true
1361				continue
1362			}
1363	
1364			backfilled++
1365		}
1366	
1367		if backfilled == 0 {
1368			if lastAgent != "" {
1369				return 0, fmt.Errorf("%w: agent %q", errTranscriptNotGeneratable, lastAgent)
1370			}
1371			if skippedNoAgent {
1372				return 0, fmt.Errorf("%w: no agent type in metadata", errTranscriptNotGeneratable)
1373			}
1374			return 0, errTranscriptNotGeneratable
1375		}
1376		if skippedBackfill {
1377			if lastAgent != "" {
1378				return backfilled, fmt.Errorf("%w: agent %q", errTranscriptNotGeneratable, lastAgent)
1379			}
1380			return backfilled, errTranscriptNotGeneratable
1381		}
1382	
1383		return backfilled, nil
1384	}
1385	
1386	func collectMissingCompactSessionsForBackfill(
1387		ctx context.Context,
1388		v2Store *checkpoint.V2GitStore,
1389		checkpointID id.CheckpointID,
1390		summary *checkpoint.CheckpointSummary,
1391	) ([]missingFullSessionForPacking, bool, error) {
1392		var missingSessions []missingFullSessionForPacking
1393		skippedNoAgent := false
1394		for sessionIdx, session := range summary.Sessions {
1395			if session.Transcript != "" {
1396				continue
1397			}
1398	
1399			meta, err := v2Store.ReadSessionMetadata(ctx, checkpointID, sessionIdx)
1400			if err != nil {
1401				return nil, false, fmt.Errorf("failed to read v2 session %d metadata while backfilling compact transcript: %w", sessionIdx, err)
1402			}
1403			if meta.Agent == "" {
1404				skippedNoAgent = true
1405				continue
1406			}
1407			missingSessions = append(missingSessions, missingFullSessionForPacking{
1408				sessionIndex: sessionIdx,
1409				sessionID:    meta.SessionID,
1410			})
1411		}
1412		return missingSessions, skippedNoAgent, nil
1413	}
