24	// ReadCommitted reads the checkpoint summary from the v2 /main ref.
25	// Returns nil, nil if the checkpoint doesn't exist (same contract as GitStore.ReadCommitted).
26	func (s *V2GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
27		if err := ctx.Err(); err != nil {
28			return nil, err //nolint:wrapcheck // Propagating context cancellation
29		}
30	
31		refName := plumbing.ReferenceName(paths.V2MainRefName)
32		_, rootTreeHash, err := s.GetRefState(refName)
33		if err != nil {
34			return nil, nil //nolint:nilnil,nilerr // Ref doesn't exist means no checkpoint
35		}
36	
37		rootTree, err := s.repo.TreeObject(rootTreeHash)
38		if err != nil {
39			return nil, nil //nolint:nilnil,nilerr // Tree not readable
40		}
41	
42		cpTree, err := rootTree.Tree(checkpointID.Path())
43		if err != nil {
44			return nil, nil //nolint:nilnil,nilerr // Checkpoint subtree not found
45		}
46	
47		cpFT := s.wrapWithFetcher(ctx, cpTree)
48		metadataFile, err := cpFT.File(paths.MetadataFileName)
49		if err != nil {
50			return nil, nil //nolint:nilnil,nilerr // metadata.json not found
51		}
52	
53		content, err := metadataFile.Contents()
54		if err != nil {
55			return nil, fmt.Errorf("failed to read metadata.json: %w", err)
56		}
57	
58		var summary CheckpointSummary
59		if err := json.Unmarshal([]byte(content), &summary); err != nil {
60			return nil, fmt.Errorf("failed to parse metadata.json: %w", err)
61		}
62	
63		return &summary, nil
64	}
