66	// ListCommitted lists all committed checkpoints from the v2 /main ref.
67	// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
68	func (s *V2GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
69		if err := ctx.Err(); err != nil {
70			return nil, err //nolint:wrapcheck // Propagating context cancellation
71		}
72	
73		refName := plumbing.ReferenceName(paths.V2MainRefName)
74		_, rootTreeHash, err := s.GetRefState(refName)
75		if err != nil {
76			return []CommittedInfo{}, nil //nolint:nilerr // No /main ref means empty list
77		}
78	
79		rootTree, err := s.repo.TreeObject(rootTreeHash)
80		if err != nil {
81			return []CommittedInfo{}, nil //nolint:nilerr // Unreadable tree means no listable entries
82		}
83	
84		var checkpoints []CommittedInfo
85	
86		_ = WalkCheckpointShards(s.repo, rootTree, func(checkpointID id.CheckpointID, cpTreeHash plumbing.Hash) error { //nolint:errcheck // callback never returns errors
87			checkpointTree, cpTreeErr := s.repo.TreeObject(cpTreeHash)
88			if cpTreeErr != nil {
89				logging.Debug(ctx, "v2 ListCommitted: skipping unreadable checkpoint tree",
90					slog.String("checkpoint_id", checkpointID.String()),
91					slog.String("error", cpTreeErr.Error()))
92				return nil
93			}
94	
95			info := CommittedInfo{CheckpointID: checkpointID}
96	
97			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
98				if content, contentErr := metadataFile.Contents(); contentErr == nil {
99					var summary CheckpointSummary
100					if unmarshalErr := json.Unmarshal([]byte(content), &summary); unmarshalErr != nil {
101						logging.Debug(ctx, "v2 ListCommitted: skipping malformed metadata",
102							slog.String("checkpoint_id", checkpointID.String()),
103							slog.String("error", unmarshalErr.Error()))
104					} else {
105						info.CheckpointsCount = summary.CheckpointsCount
106						info.FilesTouched = summary.FilesTouched
107						info.SessionCount = len(summary.Sessions)
108	
109						if len(summary.Sessions) > 0 {
110							latestIndex := len(summary.Sessions) - 1
111							latestDir := strconv.Itoa(latestIndex)
112							if sessionTree, treeErr := checkpointTree.Tree(latestDir); treeErr == nil {
113								if sessionMetadataFile, smErr := sessionTree.File(paths.MetadataFileName); smErr == nil {
114									if sessionContent, scErr := sessionMetadataFile.Contents(); scErr == nil {
115										var sessionMetadata CommittedMetadata
116										if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
117											info.Agent = sessionMetadata.Agent
118											info.SessionID = sessionMetadata.SessionID
119											info.CreatedAt = sessionMetadata.CreatedAt
120										}
121									}
122								}
123							}
124						}
125					}
126				}
127			}
128	
129			checkpoints = append(checkpoints, info)
130			return nil
131		})
132	
133		sort.Slice(checkpoints, func(i, j int) bool {
134			return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
135		})
136	
137		return checkpoints, nil
138	}
