140	// ReadSessionCompactTranscript reads transcript.jsonl for a session from the v2
141	// /main ref. Returns ErrNoTranscript when compact transcript is missing.
142	func (s *V2GitStore) ReadSessionCompactTranscript(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) ([]byte, error) {
143		if err := ctx.Err(); err != nil {
144			return nil, err //nolint:wrapcheck // Propagating context cancellation
145		}
146	
147		refName := plumbing.ReferenceName(paths.V2MainRefName)
148		_, rootTreeHash, err := s.GetRefState(refName)
149		if err != nil {
150			return nil, ErrCheckpointNotFound
151		}
152	
153		rootTree, err := s.repo.TreeObject(rootTreeHash)
154		if err != nil {
155			return nil, ErrCheckpointNotFound
156		}
157	
158		cpTree, err := rootTree.Tree(checkpointID.Path())
159		if err != nil {
160			return nil, ErrCheckpointNotFound
161		}
162	
163		sessionDir := strconv.Itoa(sessionIndex)
164		sessionTree, err := cpTree.Tree(sessionDir)
165		if err != nil {
166			return nil, ErrCheckpointNotFound
167		}
168	
169		sessionFT := s.wrapWithFetcher(ctx, sessionTree)
170		compactFile, err := sessionFT.File(paths.CompactTranscriptFileName)
171		if err != nil {
172			return nil, ErrNoTranscript
173		}
174	
175		content, err := compactFile.Contents()
176		if err != nil {
177			return nil, ErrNoTranscript
178		}
179		if content == "" {
180			return nil, ErrNoTranscript
181		}
182	
183		return []byte(content), nil
184	}
