186	// ReadSessionMetadata reads only the session's metadata.json from the v2
187	// /main ref — cheaper than ReadSessionMetadataAndPrompts when the caller
188	// only needs metadata fields (e.g. SessionID). Returns ErrCheckpointNotFound
189	// if the checkpoint or session doesn't exist on /main.
190	func (s *V2GitStore) ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (CommittedMetadata, error) {
191		if err := ctx.Err(); err != nil {
192			return CommittedMetadata{}, err //nolint:wrapcheck // Propagating context cancellation
193		}
194	
195		refName := plumbing.ReferenceName(paths.V2MainRefName)
196		_, rootTreeHash, err := s.GetRefState(refName)
197		if err != nil {
198			return CommittedMetadata{}, ErrCheckpointNotFound
199		}
200	
201		rootTree, err := s.repo.TreeObject(rootTreeHash)
202		if err != nil {
203			return CommittedMetadata{}, ErrCheckpointNotFound
204		}
205	
206		cpTree, err := rootTree.Tree(checkpointID.Path())
207		if err != nil {
208			return CommittedMetadata{}, ErrCheckpointNotFound
209		}
210	
211		sessionTree, err := cpTree.Tree(strconv.Itoa(sessionIndex))
212		if err != nil {
213			return CommittedMetadata{}, ErrCheckpointNotFound
214		}
215	
216		sessionFT := s.wrapWithFetcher(ctx, sessionTree)
217		metadataFile, err := sessionFT.File(paths.MetadataFileName)
218		if err != nil {
219			return CommittedMetadata{}, fmt.Errorf("read session metadata file: %w", err)
220		}
221		content, err := metadataFile.Contents()
222		if err != nil {
223			return CommittedMetadata{}, fmt.Errorf("read session metadata contents: %w", err)
224		}
225	
226		var meta CommittedMetadata
227		if err := json.Unmarshal([]byte(content), &meta); err != nil {
228			return CommittedMetadata{}, fmt.Errorf("parse session metadata: %w", err)
229		}
