233	// ReadSessionMetadataAndPrompts reads a session's metadata and prompts from the
234	// v2 /main ref without requiring the raw transcript from /full/* refs.
235	// Used by explain when the raw transcript is unavailable but compact transcript
236	// (transcript.jsonl) on /main can substitute for display.
237	// Returns ErrCheckpointNotFound if the checkpoint or session doesn't exist on /main.
238	func (s *V2GitStore) ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
239		if err := ctx.Err(); err != nil {
240			return nil, err //nolint:wrapcheck // Propagating context cancellation
241		}
242	
243		refName := plumbing.ReferenceName(paths.V2MainRefName)
244		_, rootTreeHash, err := s.GetRefState(refName)
245		if err != nil {
246			return nil, ErrCheckpointNotFound
247		}
248	
249		rootTree, err := s.repo.TreeObject(rootTreeHash)
250		if err != nil {
251			return nil, ErrCheckpointNotFound
252		}
253	
254		cpTree, err := rootTree.Tree(checkpointID.Path())
255		if err != nil {
256			return nil, ErrCheckpointNotFound
257		}
258	
259		sessionDir := strconv.Itoa(sessionIndex)
260		sessionTree, err := cpTree.Tree(sessionDir)
261		if err != nil {
262			return nil, ErrCheckpointNotFound
263		}
264	
265		result := &SessionContent{}
266		sessionFT := s.wrapWithFetcher(ctx, sessionTree)
267	
268		if metadataFile, fileErr := sessionFT.File(paths.MetadataFileName); fileErr == nil {
269			if content, contentErr := metadataFile.Contents(); contentErr == nil {
270				if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr != nil {
271					return nil, fmt.Errorf("failed to parse session metadata: %w", jsonErr)
272				}
273			}
274		}
275	
276		if file, fileErr := sessionFT.File(paths.PromptFileName); fileErr == nil {
277			if content, contentErr := file.Contents(); contentErr == nil {
278				result.Prompts = content
279			}
280		}
281	
282		// Read compact transcript from the same session tree (avoids a second tree walk).
283		if compactFile, fileErr := sessionFT.File(paths.CompactTranscriptFileName); fileErr == nil {
284			if content, contentErr := compactFile.Contents(); contentErr == nil && content != "" {
285				result.Transcript = []byte(content)
286			}
287		}
288	
289		return result, nil
290	}
