292	// ReadSessionContent reads a session's metadata and prompts from the v2 /main ref,
293	// and the raw transcript (raw_transcript) from /full/* refs (current + archived generations).
294	// This is the v2 equivalent of GitStore.ReadSessionContent — it reads the raw agent
295	// transcript, not the compact transcript.jsonl. Used by resume and RestoreLogsOnly.
296	// Returns ErrNoTranscript if the session exists but no raw transcript is available.
297	// Returns ErrCheckpointNotFound if the checkpoint or session doesn't exist on /main.
298	func (s *V2GitStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
299		if err := ctx.Err(); err != nil {
300			return nil, err //nolint:wrapcheck // Propagating context cancellation
301		}
302	
303		refName := plumbing.ReferenceName(paths.V2MainRefName)
304		_, rootTreeHash, err := s.GetRefState(refName)
305		if err != nil {
306			return nil, ErrCheckpointNotFound
307		}
308	
309		rootTree, err := s.repo.TreeObject(rootTreeHash)
310		if err != nil {
311			return nil, ErrCheckpointNotFound
312		}
313	
314		cpTree, err := rootTree.Tree(checkpointID.Path())
315		if err != nil {
316			return nil, ErrCheckpointNotFound
317		}
318	
319		sessionDir := strconv.Itoa(sessionIndex)
320		sessionTree, err := cpTree.Tree(sessionDir)
321		if err != nil {
322			return nil, fmt.Errorf("session %d not found: %w", sessionIndex, err)
323		}
324	
325		result := &SessionContent{}
326		sessionFT := s.wrapWithFetcher(ctx, sessionTree)
327	
328		if metadataFile, fileErr := sessionFT.File(paths.MetadataFileName); fileErr == nil {
329			if content, contentErr := metadataFile.Contents(); contentErr == nil {
330				if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr != nil {
331					return nil, fmt.Errorf("failed to parse session metadata: %w", jsonErr)
332				}
333			}
334		}
335	
336		if file, fileErr := sessionFT.File(paths.PromptFileName); fileErr == nil {
337			if content, contentErr := file.Contents(); contentErr == nil {
338				result.Prompts = content
339			}
340		}
341	
342		transcript, transcriptErr := s.readTranscriptFromFullRefs(ctx, checkpointID, sessionIndex, result.Metadata.Agent)
343		if transcriptErr != nil {
344			return nil, fmt.Errorf("failed to read transcript from /full/* refs: %w", transcriptErr)
345		}
346		if len(transcript) == 0 {
347			return nil, ErrNoTranscript
348		}
349		result.Transcript = transcript
350	
351		return result, nil
352	}
