354	// readTranscriptFromFullRefs reads the raw transcript for a checkpoint session
355	// by searching /full/current first, then archived generations in reverse order.
356	// If not found locally, attempts to discover and fetch remote /full/* refs.
357	func (s *V2GitStore) readTranscriptFromFullRefs(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int, agentType types.AgentType) ([]byte, error) {
358		if err := ctx.Err(); err != nil {
359			return nil, err //nolint:wrapcheck // Propagating context cancellation
360		}
361	
362		sessionPath := fmt.Sprintf("%s/%d", checkpointID.Path(), sessionIndex)
363	
364		// Search locally first
365		transcript, err := s.readTranscriptFromRef(plumbing.ReferenceName(paths.V2FullCurrentRefName), sessionPath, agentType)
366		if err == nil && len(transcript) > 0 {
367			return transcript, nil
368		}
369	
370		archived, err := s.ListArchivedGenerations()
371		if err != nil {
372			return nil, err
373		}
374		for i := len(archived) - 1; i >= 0; i-- {
375			refName := plumbing.ReferenceName(paths.V2FullRefPrefix + archived[i])
376			transcript, err := s.readTranscriptFromRef(refName, sessionPath, agentType)
377			if err == nil && len(transcript) > 0 {
378				return transcript, nil
379			}
380		}
381	
382		// Not found locally — try fetching remote /full/* refs
383		if fetchErr := s.fetchRemoteFullRefs(ctx); fetchErr != nil {
384			logging.Debug(ctx, "failed to fetch remote /full/* refs",
385				slog.String("error", fetchErr.Error()),
386			)
387			return nil, nil
388		}
389	
390		// Search newly fetched refs only
391		newArchived, err := s.ListArchivedGenerations()
392		if err != nil {
393			return nil, nil //nolint:nilerr // Best-effort: fetch-on-demand failure shouldn't block resume
394		}
395		existingSet := make(map[string]bool, len(archived))
396		for _, a := range archived {
397			existingSet[a] = true
398		}
399		for i := len(newArchived) - 1; i >= 0; i-- {
400			if existingSet[newArchived[i]] {
401				continue
402			}
403			refName := plumbing.ReferenceName(paths.V2FullRefPrefix + newArchived[i])
404			transcript, err := s.readTranscriptFromRef(refName, sessionPath, agentType)
405			if err == nil && len(transcript) > 0 {
406				return transcript, nil
407			}
408		}
409	
410		// Also retry /full/current in case it was updated by the fetch
411		transcript, err = s.readTranscriptFromRef(plumbing.ReferenceName(paths.V2FullCurrentRefName), sessionPath, agentType)
412		if err == nil && len(transcript) > 0 {
413			return transcript, nil
414		}
415	
416		return nil, nil
417	}
418	
419	// fetchRemoteFullRefs discovers and fetches /full/* refs from the configured
420	// FetchRemote that aren't local.
421	func (s *V2GitStore) fetchRemoteFullRefs(ctx context.Context) error {
422		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
423		defer cancel()
424	
425		lsCmd := exec.CommandContext(ctx, "git", "ls-remote", s.FetchRemote, paths.V2FullRefPrefix+"*")
426		output, err := lsCmd.Output()
427		if err != nil {
428			return fmt.Errorf("ls-remote failed: %w", err)
429		}
430	
431		var refSpecs []string
432		for _, line := range strings.Split(strings.TrimSpace(string(output)), "\n") {
433			if line == "" {
434				continue
435			}
436			parts := strings.Fields(line)
437			if len(parts) < 2 {
438				continue
439			}
440			remoteRefName := parts[1]
441	
442			// Skip refs that already exist locally
443			if _, refErr := s.repo.Reference(plumbing.ReferenceName(remoteRefName), true); refErr == nil {
444				continue
445			}
446	
447			refSpecs = append(refSpecs, fmt.Sprintf("+%s:%s", remoteRefName, remoteRefName))
448		}
449	
450		if len(refSpecs) == 0 {
451			return nil
452		}
453	
454		args := append([]string{"fetch", "--no-tags", s.FetchRemote}, refSpecs...)
455		fetchCmd := exec.CommandContext(ctx, "git", args...)
456		if fetchOutput, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
457			return fmt.Errorf("fetch failed: %s", fetchOutput)
458		}
459	
460		return nil
461	}
