463	// readTranscriptFromRef reads the raw transcript from a specific /full/* ref.
464	// Follows the same chunking convention as readTranscriptFromTree in committed.go:
465	// chunk 0 is the base file (raw_transcript), chunks 1+ are raw_transcript.001, .002, etc.
466	// When chunk files exist, all chunks (including chunk 0) are reassembled using
467	// agent-aware reassembly via agent.ReassembleTranscript.
468	func (s *V2GitStore) readTranscriptFromRef(refName plumbing.ReferenceName, sessionPath string, agentType types.AgentType) ([]byte, error) {
469		_, rootTreeHash, err := s.GetRefState(refName)
470		if err != nil {
471			return nil, err
472		}
473	
474		rootTree, err := s.repo.TreeObject(rootTreeHash)
475		if err != nil {
476			return nil, fmt.Errorf("failed to read tree: %w", err)
477		}
478	
479		sessionTree, err := rootTree.Tree(sessionPath)
480		if err != nil {
481			return nil, fmt.Errorf("session path %s not found: %w", sessionPath, err)
482		}
483	
484		return readTranscriptFromObjectTree(sessionTree, agentType)
485	}
486	
487	// readTranscriptFromObjectTree reads and reassembles a transcript from a git tree object.
488	// Handles both chunked and non-chunked transcripts. Uses agent-aware reassembly
489	// when agentType is known, falling back to JSONL reassembly otherwise.
490	func readTranscriptFromObjectTree(tree *object.Tree, agentType types.AgentType) ([]byte, error) {
491		var chunkFiles []string
492		var hasBaseFile bool
493	
494		for _, entry := range tree.Entries {
495			if entry.Name == paths.V2RawTranscriptFileName {
496				hasBaseFile = true
497			}
498			if strings.HasPrefix(entry.Name, paths.V2RawTranscriptFileName+".") {
499				idx := agent.ParseChunkIndex(entry.Name, paths.V2RawTranscriptFileName)
500				if idx > 0 {
501					chunkFiles = append(chunkFiles, entry.Name)
502				}
503			}
504		}
505	
506		// If chunk files exist, reassemble all chunks (base file is chunk 0)
507		if len(chunkFiles) > 0 {
508			chunkFiles = agent.SortChunkFiles(chunkFiles, paths.V2RawTranscriptFileName)
509			if hasBaseFile {
510				chunkFiles = append([]string{paths.V2RawTranscriptFileName}, chunkFiles...)
511			}
512	
513			var chunks [][]byte
514			for _, chunkFile := range chunkFiles {
515				file, fileErr := tree.File(chunkFile)
516				if fileErr != nil {
517					continue
518				}
519				content, contentErr := file.Contents()
520				if contentErr != nil {
521					continue
522				}
523				chunks = append(chunks, []byte(content))
524			}
525	
526			if len(chunks) > 0 {
527				result, reassembleErr := agent.ReassembleTranscript(chunks, agentType)
528				if reassembleErr != nil {
529					return nil, fmt.Errorf("failed to reassemble transcript: %w", reassembleErr)
530				}
531				return result, nil
532			}
533		}
534	
535		// No chunk files — read base file directly (non-chunked transcript)
536		if hasBaseFile {
537			file, err := tree.File(paths.V2RawTranscriptFileName)
538			if err == nil {
539				content, contentErr := file.Contents()
540				if contentErr == nil {
541					return []byte(content), nil
542				}
543			}
544		}
545	
546		return nil, nil
547	}
