549	// ReadSessionContentByID finds the session with the given sessionID in a checkpoint
550	// and returns its content. Mirrors GitStore.ReadSessionContentByID for v2 refs.
551	// Returns ErrCheckpointNotFound if the checkpoint doesn't exist; returns a
552	// non-wrapped error (containing the session ID and checkpoint ID for context)
553	// if no session in the checkpoint matches sessionID.
554	func (s *V2GitStore) ReadSessionContentByID(ctx context.Context, checkpointID id.CheckpointID, sessionID string) (*SessionContent, error) {
555		summary, err := s.ReadCommitted(ctx, checkpointID)
556		if err != nil {
557			return nil, err
558		}
559		if summary == nil {
560			return nil, ErrCheckpointNotFound
561		}
562	
563		for i := range summary.Sessions {
564			content, readErr := s.ReadSessionContent(ctx, checkpointID, i)
565			if readErr != nil {
566				continue
567			}
568			if content != nil && content.Metadata.SessionID == sessionID {
569				return content, nil
570			}
571		}
572	
573		return nil, fmt.Errorf("session %q not found in checkpoint %s", sessionID, checkpointID)
574	}
575	
576	// GetSessionLog reads the latest session's raw transcript and session ID from v2 refs.
577	// Convenience wrapper matching the GitStore.GetSessionLog signature.
578	func (s *V2GitStore) GetSessionLog(ctx context.Context, cpID id.CheckpointID) ([]byte, string, error) {
579		summary, err := s.ReadCommitted(ctx, cpID)
580		if err != nil {
581			return nil, "", err
582		}
583		if summary == nil {
584			return nil, "", ErrCheckpointNotFound
585		}
586		if len(summary.Sessions) == 0 {
587			return nil, "", ErrCheckpointNotFound
588		}
589	
590		latestIndex := len(summary.Sessions) - 1
591		content, err := s.ReadSessionContent(ctx, cpID, latestIndex)
592		if err != nil {
593			return nil, "", err
594		}
595		return content.Transcript, content.Metadata.SessionID, nil
596	}
