29	// WriteCommitted writes a committed checkpoint to both v2 refs:
30	//   - /main: metadata and prompts (no raw transcript or content hash)
31	//   - /full/current: raw transcript + content hash (replaces previous content)
32	//
33	// This is the public entry point for v2 dual-writes. The session index is
34	// determined from the /main ref and passed to the /full/current write to
35	// keep both refs consistent.
36	func (s *V2GitStore) WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error {
37		_, err := s.WriteCommittedWithSessionIndex(ctx, opts)
38		return err
39	}
40	
41	// WriteCommittedWithSessionIndex writes a committed checkpoint and returns the
42	// v2 session index used for the write. The index may point at an existing
43	// session when the checkpoint already contains the same session ID.
44	func (s *V2GitStore) WriteCommittedWithSessionIndex(ctx context.Context, opts WriteCommittedOptions) (int, error) {
45		// Validate upfront before any writes to avoid partial ref updates
46		if err := validateWriteOpts(opts); err != nil {
47			return 0, err
48		}
49	
50		sessionIndex, err := s.writeCommittedMain(ctx, opts)
51		if err != nil {
52			return 0, fmt.Errorf("v2 /main write failed: %w", err)
53		}
54	
55		if err := s.writeCommittedFullTranscript(ctx, opts, sessionIndex); err != nil {
56			return 0, fmt.Errorf("v2 /full/current write failed: %w", err)
57		}
58	
59		return sessionIndex, nil
60	}
