62	// UpdateCommitted replaces the prompts and/or transcript for an existing v2
63	// checkpoint. Called at stop time to finalize checkpoints with the complete
64	// session transcript.
65	//
66	// On /main: replaces prompts and compact transcript (if provided).
67	// On /full/*: replaces the raw transcript where the session artifacts already
68	// live, or writes to /full/current if the session has no full artifacts yet.
69	//
70	// Returns ErrCheckpointNotFound if the checkpoint doesn't exist on /main.
71	func (s *V2GitStore) UpdateCommitted(ctx context.Context, opts UpdateCommittedOptions) error {
72		if opts.CheckpointID.IsEmpty() {
73			return errors.New("invalid update options: checkpoint ID is required")
74		}
75	
76		sessionIndex, err := s.updateCommittedMain(ctx, opts)
77		if err != nil {
78			return fmt.Errorf("v2 /main update failed: %w", err)
79		}
80	
81		if opts.Transcript.Len() > 0 {
82			if err := s.updateCommittedFullTranscript(ctx, opts, sessionIndex); err != nil {
83				return fmt.Errorf("v2 /full/* update failed: %w", err)
84			}
85		}
86	
87		return nil
88	}
