90	// fullSessionArtifacts describes where a checkpoint session's raw transcript
91	// artifacts live across the v2 /full/* refs.
92	type fullSessionArtifacts struct {
93		RefName       plumbing.ReferenceName
94		Found         bool
95		HasTranscript bool
96		HasHash       bool
97	}
98	
99	// HasFullSessionArtifacts reports whether the raw transcript and content hash
100	// for a checkpoint session exist in any local v2 /full/* ref.
101	func (s *V2GitStore) HasFullSessionArtifacts(checkpointID id.CheckpointID, sessionIndex int) (bool, error) {
102		artifacts, err := s.findFullSessionArtifacts(checkpointID, sessionIndex)
103		if err != nil {
104			return false, err
105		}
106		return artifacts.Found && artifacts.HasTranscript && artifacts.HasHash, nil
107	}
