109	func (s *V2GitStore) findFullSessionArtifacts(checkpointID id.CheckpointID, sessionIndex int) (fullSessionArtifacts, error) {
110		refNames, err := s.fullRefSearchOrder()
111		if err != nil {
112			return fullSessionArtifacts{}, err
113		}
114	
115		var firstFound fullSessionArtifacts
116		for _, refName := range refNames {
117			artifacts, inspectErr := s.inspectFullSessionArtifacts(refName, checkpointID, sessionIndex)
118			if inspectErr != nil {
119				return fullSessionArtifacts{}, inspectErr
120			}
121			if !artifacts.Found {
122				continue
123			}
124			if artifacts.HasTranscript && artifacts.HasHash {
125				return artifacts, nil
126			}
127			if !firstFound.Found {
128				firstFound = artifacts
129			}
130		}
131	
132		if firstFound.Found {
133			return firstFound, nil
134		}
135	
136		return fullSessionArtifacts{}, nil
137	}
