139	// FullSessionArtifactsIndex answers "does this session have complete /full/*
140	// artifacts?" with an O(1) map lookup. Build it once via
141	// BuildFullSessionArtifactsIndex.
142	type FullSessionArtifactsIndex map[string]struct{}
143	
144	// Has reports whether the given session has a complete pair of
145	// raw_transcript and raw_transcript_hash.txt entries in some /full/* ref.
146	func (idx FullSessionArtifactsIndex) Has(checkpointID id.CheckpointID, sessionIndex int) bool {
147		if idx == nil {
148			return false
149		}
150		_, ok := idx[fullArtifactsIndexKey(checkpointID, sessionIndex)]
151		return ok
152	}
153	
154	func fullArtifactsIndexKey(checkpointID id.CheckpointID, sessionIndex int) string {
155		return string(checkpointID) + "/" + strconv.Itoa(sessionIndex)
156	}
157	
158	// BuildFullSessionArtifactsIndex walks every /full/* ref's tree once and
159	// records sessions whose subtree contains both raw_transcript[/.NNN] and
160	// raw_transcript_hash.txt. Amortizes per-session HasFullSessionArtifacts
161	// calls — each of which would otherwise list every git ref and re-walk every
162	// /full/* tree — across the rest of the run.
163	func (s *V2GitStore) BuildFullSessionArtifactsIndex() (FullSessionArtifactsIndex, error) {
164		refNames, err := s.fullRefSearchOrder()
165		if err != nil {
166			return nil, err
167		}
168	
169		index := make(FullSessionArtifactsIndex)
170		for _, refName := range refNames {
171			_, rootTreeHash, refErr := s.GetRefState(refName)
172			if refErr != nil {
173				if errors.Is(refErr, plumbing.ErrReferenceNotFound) {
174					continue
175				}
176				return nil, fmt.Errorf("read %s: %w", refName, refErr)
177			}
178			rootTree, treeErr := s.repo.TreeObject(rootTreeHash)
179			if treeErr != nil {
180				return nil, fmt.Errorf("read %s root tree: %w", refName, treeErr)
181			}
182			if err := s.indexFullSessionsInTree(rootTree, index); err != nil {
183				return nil, fmt.Errorf("walk %s: %w", refName, err)
184			}
185		}
186		return index, nil
187	}
188	
189	func (s *V2GitStore) indexFullSessionsInTree(rootTree *object.Tree, index FullSessionArtifactsIndex) error {
190		for _, shardEntry := range rootTree.Entries {
191			if shardEntry.Mode != filemode.Dir || len(shardEntry.Name) != 2 {
192				continue
193			}
194			shardTree, err := s.repo.TreeObject(shardEntry.Hash)
195			if err != nil {
196				return fmt.Errorf("read shard %s: %w", shardEntry.Name, err)
197			}
198			for _, cpEntry := range shardTree.Entries {
199				if cpEntry.Mode != filemode.Dir {
200					continue
201				}
202				cpTree, err := s.repo.TreeObject(cpEntry.Hash)
203				if err != nil {
204					return fmt.Errorf("read checkpoint tree %s/%s: %w", shardEntry.Name, cpEntry.Name, err)
205				}
206				cpid := id.CheckpointID(shardEntry.Name + cpEntry.Name)
207				for _, sessionEntry := range cpTree.Entries {
208					if sessionEntry.Mode != filemode.Dir {
209						continue
210					}
211					sessionIdx, atoiErr := strconv.Atoi(sessionEntry.Name)
212					if atoiErr != nil {
213						continue
214					}
215					sessionTree, err := s.repo.TreeObject(sessionEntry.Hash)
216					if err != nil {
217						return fmt.Errorf("read session tree %s/%s/%d: %w", shardEntry.Name, cpEntry.Name, sessionIdx, err)
218					}
219					if !sessionHasCompleteFullArtifacts(sessionTree.Entries) {
220						continue
221					}
222					index[fullArtifactsIndexKey(cpid, sessionIdx)] = struct{}{}
223				}
224			}
225		}
226		return nil
227	}
228	
229	func sessionHasCompleteFullArtifacts(entries []object.TreeEntry) bool {
230		hasTranscript := false
231		hasHash := false
232		for _, entry := range entries {
233			switch {
234			case entry.Name == paths.V2RawTranscriptFileName,
235				strings.HasPrefix(entry.Name, paths.V2RawTranscriptFileName+"."):
236				hasTranscript = true
237			case entry.Name == paths.V2RawTranscriptHashFileName:
238				hasHash = true
239			}
240		}
241		return hasTranscript && hasHash
242	}
