244	func (s *V2GitStore) fullRefSearchOrder() ([]plumbing.ReferenceName, error) {
245		refNames := []plumbing.ReferenceName{plumbing.ReferenceName(paths.V2FullCurrentRefName)}
246	
247		archived, err := s.ListArchivedGenerations()
248		if err != nil {
249			return nil, err
250		}
251		for i := len(archived) - 1; i >= 0; i-- {
252			refNames = append(refNames, plumbing.ReferenceName(paths.V2FullRefPrefix+archived[i]))
253		}
254	
255		return refNames, nil
256	}
