258	func (s *V2GitStore) inspectFullSessionArtifacts(refName plumbing.ReferenceName, checkpointID id.CheckpointID, sessionIndex int) (fullSessionArtifacts, error) {
259		_, rootTreeHash, err := s.GetRefState(refName)
260		if err != nil {
261			if errors.Is(err, plumbing.ErrReferenceNotFound) {
262				return fullSessionArtifacts{}, nil
263			}
264			return fullSessionArtifacts{}, err
265		}
266	
267		rootTree, err := s.repo.TreeObject(rootTreeHash)
268		if err != nil {
269			return fullSessionArtifacts{}, fmt.Errorf("failed to read %s tree: %w", refName, err)
270		}
271	
272		sessionPath := fmt.Sprintf("%s/%d", checkpointID.Path(), sessionIndex)
273		sessionTree, err := rootTree.Tree(sessionPath)
274		if err != nil {
275			if errors.Is(err, object.ErrDirectoryNotFound) {
276				return fullSessionArtifacts{}, nil
277			}
278			return fullSessionArtifacts{}, fmt.Errorf("failed to read %s session tree %s: %w", refName, sessionPath, err)
279		}
280	
281		artifacts := fullSessionArtifacts{RefName: refName, Found: true}
282		for _, entry := range sessionTree.Entries {
283			switch {
284			case entry.Name == paths.V2RawTranscriptFileName:
285				artifacts.HasTranscript = true
286			case strings.HasPrefix(entry.Name, paths.V2RawTranscriptFileName+"."):
287				artifacts.HasTranscript = true
288			case entry.Name == paths.V2RawTranscriptHashFileName:
289				artifacts.HasHash = true
290			}
291		}
292	
293		return artifacts, nil
294	}
