296	// updateCommittedMain updates prompts and compact transcript on the /main ref for an existing checkpoint.
297	// Returns the session index for coordination with /full/current.
298	func (s *V2GitStore) updateCommittedMain(ctx context.Context, opts UpdateCommittedOptions) (int, error) {
299		refName := plumbing.ReferenceName(paths.V2MainRefName)
300		parentHash, rootTreeHash, err := s.GetRefState(refName)
301		if err != nil {
302			return 0, ErrCheckpointNotFound
303		}
304	
305		basePath := opts.CheckpointID.Path() + "/"
306		checkpointPath := opts.CheckpointID.Path()
307	
308		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
309		if err != nil {
310			return 0, err
311		}
312	
313		rootMetadataPath := basePath + paths.MetadataFileName
314		entry, exists := entries[rootMetadataPath]
315		if !exists {
316			return 0, ErrCheckpointNotFound
317		}
318	
319		summary, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
320		if err != nil {
321			return 0, fmt.Errorf("failed to read checkpoint summary: %w", err)
322		}
323		if len(summary.Sessions) == 0 {
324			return 0, ErrCheckpointNotFound
325		}
326	
327		// Find session index by ID, fall back to latest
328		sessionIndex := s.gs.findSessionIndex(ctx, basePath, summary, entries, opts.SessionID)
329		if sessionIndex >= len(summary.Sessions) {
330			// findSessionIndex returns next-available when not found; fall back to latest
331			sessionIndex = len(summary.Sessions) - 1
332			logging.Debug(ctx, "v2 UpdateCommitted: session ID not found, falling back to latest",
333				slog.String("session_id", opts.SessionID),
334				slog.String("checkpoint_id", string(opts.CheckpointID)),
335				slog.Int("fallback_index", sessionIndex),
336			)
337		}
338	
339		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
340	
341		if len(opts.Prompts) > 0 {
342			promptContent := redact.String(JoinPrompts(opts.Prompts))
343			blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
344			if err != nil {
345				return 0, fmt.Errorf("failed to create prompt blob: %w", err)
346			}
347			entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
348				Name: sessionPath + paths.PromptFileName,
349				Mode: filemode.Regular,
350				Hash: blobHash,
351			}
352		}
353	
354		// Replace compact transcript if provided
355		if len(opts.CompactTranscript) > 0 {
356			blobHash, err := CreateBlobFromContent(s.repo, opts.CompactTranscript)
357			if err != nil {
358				return 0, fmt.Errorf("failed to create compact transcript blob: %w", err)
359			}
360			entries[sessionPath+paths.CompactTranscriptFileName] = object.TreeEntry{
361				Name: sessionPath + paths.CompactTranscriptFileName,
362				Mode: filemode.Regular,
363				Hash: blobHash,
364			}
365	
366			if err := s.writeCompactTranscriptHash(opts.CompactTranscript, sessionPath, entries); err != nil {
367				return 0, fmt.Errorf("failed to write compact transcript hash: %w", err)
368			}
369	
370			// Keep root checkpoint summary in sync with compact artifact paths.
371			if sessionIndex >= 0 && sessionIndex < len(summary.Sessions) {
372				summary.Sessions[sessionIndex].Transcript = "/" + sessionPath + paths.CompactTranscriptFileName
373				summary.Sessions[sessionIndex].ContentHash = "/" + sessionPath + paths.CompactTranscriptHashFileName
374	
375				summaryBytes, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
376				if err != nil {
377					return 0, fmt.Errorf("failed to marshal checkpoint summary: %w", err)
378				}
379				summaryHash, err := CreateBlobFromContent(s.repo, summaryBytes)
380				if err != nil {
381					return 0, fmt.Errorf("failed to create checkpoint summary blob: %w", err)
382				}
383				entries[rootMetadataPath] = object.TreeEntry{
384					Name: rootMetadataPath,
385					Mode: filemode.Regular,
386					Hash: summaryHash,
387				}
388			}
389		}
390	
391		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, opts.CheckpointID, basePath, entries)
392		if err != nil {
393			return 0, err
394		}
395	
396		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
397		commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
398		if err := s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail); err != nil {
399			return 0, err
400		}
401	
402		return sessionIndex, nil
403	}
404	
405	// updateCommittedFullTranscript replaces the transcript for a specific checkpoint
406	// on the /full/* ref where that checkpoint session already lives, while
407	// preserving other checkpoints' transcripts in the tree. If the session has no
408	// full-transcript artifacts yet, it writes to /full/current.
409	func (s *V2GitStore) updateCommittedFullTranscript(ctx context.Context, opts UpdateCommittedOptions, sessionIndex int) error {
410		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
411	
412		existing, findErr := s.findFullSessionArtifacts(opts.CheckpointID, sessionIndex)
413		if findErr != nil {
414			return findErr
415		}
416		if existing.Found {
417			refName = existing.RefName
418		}
419	
420		if refName == plumbing.ReferenceName(paths.V2FullCurrentRefName) {
421			if err := s.ensureRef(ctx, refName); err != nil {
422				return fmt.Errorf("failed to ensure /full/current ref: %w", err)
423			}
424		}
425	
426		parentHash, rootTreeHash, err := s.GetRefState(refName)
427		if err != nil {
428			return err
429		}
430	
431		basePath := opts.CheckpointID.Path() + "/"
432		checkpointPath := opts.CheckpointID.Path()
433		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
434	
435		// Read existing entries and replace transcript for this checkpoint only
436		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
437		if err != nil {
438			return err
439		}
440	
441		// Ignore precompute if invariants are violated — fall back to fresh chunking.
442		precomputed := opts.PrecomputedBlobs
443		if precomputed != nil && !precomputed.isUsable() {
444			precomputed = nil
445		}
446	
447		// Short-circuit: if the existing raw_transcript_hash.txt already matches
448		// the new transcript's sha256, the existing chunk entries represent the
449		// same content — preserve them and skip chunking + zlib.
450		rawTranscriptPath := sessionPath + paths.V2RawTranscriptFileName
451		rawHashPath := sessionPath + paths.V2RawTranscriptHashFileName
452		var newContentHash string
453		if precomputed != nil {
454			newContentHash = precomputed.ContentHash
455		} else {
456			newContentHash = fmt.Sprintf("sha256:%x", sha256.Sum256(opts.Transcript.Bytes()))
457		}
458		if existing, ok := entries[rawHashPath]; ok {
459			if blob, err := s.repo.BlobObject(existing.Hash); err == nil {
460				if rdr, rerr := blob.Reader(); rerr == nil {
461					existingHash, readErr := io.ReadAll(rdr)
462					_ = rdr.Close()
463					if readErr == nil && string(existingHash) == newContentHash {
464						// Content unchanged — skip tree surgery and ref advance to
465						// avoid a no-op commit on /full/current. The existing ref
466						// already references the correct tree.
467						return nil
468					}
469				}
470			}
471		}
472	
473		// Clear existing transcript artifacts for this session path before writing new ones.
474		// Preserve non-transcript metadata under the same session (e.g., tasks/*).
475		for key := range entries {
476			switch {
477			case key == rawTranscriptPath:
478				delete(entries, key)
479			case strings.HasPrefix(key, rawTranscriptPath+"."):
480				delete(entries, key)
481			case key == rawHashPath:
482				delete(entries, key)
483			}
484		}
485	
486		if err := s.writeTranscriptBlobs(ctx, opts.Transcript, opts.Agent, precomputed, sessionPath, entries); err != nil {
487			return err
488		}
489	
490		if err := s.writeContentHashFromPrecompute(newContentHash, precomputed, sessionPath, entries); err != nil {
491			return err
492		}
493	
494		// Splice into existing root tree (preserves other checkpoints' transcripts)
495		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, opts.CheckpointID, basePath, entries)
496		if err != nil {
497			return err
498		}
499	
500		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
501		commitMsg := fmt.Sprintf("Finalize checkpoint: %s\n", opts.CheckpointID)
502		if err := s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail); err != nil {
503			return err
504		}
505	
506		if refName == plumbing.ReferenceName(paths.V2FullCurrentRefName) {
507			s.rotateCurrentIfNeeded(ctx, newTreeHash)
508		}
509	
510		return nil
511	}
512	
513	// writeCommittedMain writes metadata entries to the /main ref.
514	// This includes session metadata and prompts — but NOT the raw transcript
515	// (raw_transcript) or content hash (raw_transcript_hash.txt), which go to /full/current.
516	// Returns the session index used, so the caller can pass it to writeCommittedFullTranscript.
517	func (s *V2GitStore) writeCommittedMain(ctx context.Context, opts WriteCommittedOptions) (int, error) {
518		refName := plumbing.ReferenceName(paths.V2MainRefName)
519		if err := s.ensureRef(ctx, refName); err != nil {
520			return 0, fmt.Errorf("failed to ensure /main ref: %w", err)
521		}
522	
523		parentHash, rootTreeHash, err := s.GetRefState(refName)
524		if err != nil {
525			return 0, err
526		}
527	
528		basePath := opts.CheckpointID.Path() + "/"
529		checkpointPath := opts.CheckpointID.Path()
530	
531		// Read existing entries at this checkpoint's shard path
532		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
533		if err != nil {
534			return 0, err
535		}
536	
537		// Build main session entries (metadata, prompts — no transcript or content hash)
538		sessionIndex, err := s.writeMainCheckpointEntries(ctx, opts, basePath, entries)
539		if err != nil {
540			return 0, err
541		}
542	
543		// Splice entries into root tree
544		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, opts.CheckpointID, basePath, entries)
545		if err != nil {
546			return 0, err
547		}
548	
549		commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
550		if err := s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
551			return 0, err
552		}
553		return sessionIndex, nil
554	}
555	
556	// writeMainCheckpointEntries orchestrates writing session data to the /main ref.
557	// It mirrors GitStore.writeStandardCheckpointEntries but excludes raw transcript blobs.
558	// Returns the session index used, for coordination with writeCommittedFullTranscript.
559	func (s *V2GitStore) writeMainCheckpointEntries(ctx context.Context, opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (int, error) {
560		// Read existing summary to get current session count
561		var existingSummary *CheckpointSummary
562		metadataPath := basePath + paths.MetadataFileName
563		if entry, exists := entries[metadataPath]; exists {
564			existing, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
565			if err == nil {
566				existingSummary = existing
567			}
568		}
569	
570		// Determine session index
571		sessionIndex := s.gs.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)
572	
573		// Refuse if slot 0 already holds metadata for a DIFFERENT session ID.
574		// Mirrors GitStore.writeStandardCheckpointEntries: findSessionIndex only
575		// picks slot 0 when existingSummary is nil or when the summary claims slot 0
576		// belongs to us, so the actual tree holding session-0 metadata for someone
577		// else is a corruption / stale-summary shape. Read BEFORE
578		// writeMainSessionToSubdirectory clears the subtree, or we'd only ever see
579		// our own write.
580		if sessionIndex == 0 {
581			if entry, exists := entries[fmt.Sprintf("%s0/%s", basePath, paths.MetadataFileName)]; exists {
582				if existingMeta, readErr := s.gs.readMetadataFromBlob(entry.Hash); readErr == nil && existingMeta.SessionID != opts.SessionID {
583					logging.Error(ctx, "refusing v2 checkpoint write: session 0 holds a different sessionID",
584						slog.String("checkpoint_id", opts.CheckpointID.String()),
585						slog.String("existing_session_id", existingMeta.SessionID),
586						slog.String("write_session_id", opts.SessionID),
587						slog.Bool("existing_summary_nil", existingSummary == nil))
588					return 0, fmt.Errorf(
589						"refusing to overwrite session 0 of checkpoint %s: existing session ID %q differs from write session ID %q. The v2 checkpoint tree is inconsistent (session 0 belongs to a different session than this write claims). No automated repair exists for this shape — please report it along with the output of `git ls-tree %s %s/`",
590						opts.CheckpointID, existingMeta.SessionID, opts.SessionID, paths.V2MainRefName, opts.CheckpointID.Path(),
591					)
592				}
593			}
594		}
595	
596		// Write session files (metadata and prompts — no transcript or content hash)
597		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
598		sessionFilePaths, err := s.writeMainSessionToSubdirectory(opts, sessionPath, entries)
599		if err != nil {
600			return 0, err
601		}
602	
603		// Build the sessions array
604		var sessions []SessionFilePaths
605		if existingSummary != nil {
606			sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
607			copy(sessions, existingSummary.Sessions)
608		} else {
609			sessions = make([]SessionFilePaths, 1)
610		}
611		sessions[sessionIndex] = sessionFilePaths
612	
613		// Write root CheckpointSummary
614		if err := s.gs.writeCheckpointSummary(opts, basePath, entries, sessions); err != nil {
615			return 0, err
616		}
617		return sessionIndex, nil
618	}
619	
620	// writeMainSessionToSubdirectory writes a single session's metadata, prompts,
621	// and compact transcript to a session subdirectory (0/, 1/, 2/, … indexed by
622	// session order within the checkpoint). The raw transcript (raw_transcript) and its
623	// content hash (raw_transcript_hash.txt) go to /full/current, not here.
624	func (s *V2GitStore) writeMainSessionToSubdirectory(opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
625		filePaths := SessionFilePaths{}
626	
627		// Clear existing entries at this session path
628		for key := range entries {
629			if strings.HasPrefix(key, sessionPath) {
630				delete(entries, key)
631			}
632		}
633	
634		// Write prompts
635		if len(opts.Prompts) > 0 {
636			promptContent := redact.String(JoinPrompts(opts.Prompts))
637			blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
638			if err != nil {
639				return filePaths, err
640			}
641			entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
642				Name: sessionPath + paths.PromptFileName,
643				Mode: filemode.Regular,
644				Hash: blobHash,
645			}
646			filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
647		}
648	
649		// Write compact transcript (transcript.jsonl) + hash if provided
650		if len(opts.CompactTranscript) > 0 {
651			blobHash, err := CreateBlobFromContent(s.repo, opts.CompactTranscript)
652			if err != nil {
653				return filePaths, fmt.Errorf("failed to create compact transcript blob: %w", err)
654			}
655			entries[sessionPath+paths.CompactTranscriptFileName] = object.TreeEntry{
656				Name: sessionPath + paths.CompactTranscriptFileName,
657				Mode: filemode.Regular,
658				Hash: blobHash,
659			}
660			filePaths.Transcript = "/" + sessionPath + paths.CompactTranscriptFileName
661	
662			if err := s.writeCompactTranscriptHash(opts.CompactTranscript, sessionPath, entries); err != nil {
663				return filePaths, fmt.Errorf("failed to write compact transcript hash: %w", err)
664			}
665			filePaths.ContentHash = "/" + sessionPath + paths.CompactTranscriptHashFileName
666		}
667	
668		// Write session metadata
669		sessionMetadata := CommittedMetadata{
670			CheckpointID:                opts.CheckpointID,
671			SessionID:                   opts.SessionID,
672			Strategy:                    opts.Strategy,
673			CreatedAt:                   checkpointCreatedAt(opts),
674			Branch:                      opts.Branch,
675			CheckpointsCount:            opts.CheckpointsCount,
676			FilesTouched:                opts.FilesTouched,
677			Agent:                       opts.Agent,
678			Model:                       opts.Model,
679			TurnID:                      opts.TurnID,
680			IsTask:                      opts.IsTask,
681			ToolUseID:                   opts.ToolUseID,
682			TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
683			CheckpointTranscriptStart:   opts.CompactTranscriptStart,
684			TokenUsage:                  opts.TokenUsage,
685			SessionMetrics:              opts.SessionMetrics,
686			InitialAttribution:          opts.InitialAttribution,
687			PromptAttributions:          opts.PromptAttributionsJSON,
688			Summary:                     redactSummary(opts.Summary),
689			CLIVersion:                  versioninfo.Version,
690		}
691	
692		metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
693		if err != nil {
694			return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
695		}
696		metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
697		if err != nil {
698			return filePaths, err
699		}
700		entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
701			Name: sessionPath + paths.MetadataFileName,
702			Mode: filemode.Regular,
703			Hash: metadataHash,
704		}
705		filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName
706	
707		return filePaths, nil
708	}
709	
710	// writeCompactTranscriptHash computes and writes the SHA-256 hash of the compact transcript.
711	func (s *V2GitStore) writeCompactTranscriptHash(compactTranscript []byte, sessionPath string, entries map[string]object.TreeEntry) error {
712		hash := fmt.Sprintf("sha256:%x", sha256.Sum256(compactTranscript))
713		blobHash, err := CreateBlobFromContent(s.repo, []byte(hash))
714		if err != nil {
715			return err
716		}
717		entries[sessionPath+paths.CompactTranscriptHashFileName] = object.TreeEntry{
718			Name: sessionPath + paths.CompactTranscriptHashFileName,
719			Mode: filemode.Regular,
720			Hash: blobHash,
721		}
722		return nil
723	}
724	
725	// writeCommittedFullTranscript writes the raw transcript to the /full/current ref.
726	// Transcripts accumulate across checkpoints — each write splices into the existing
727	// tree. Generation metadata (generation.json) at the tree root is updated on every
728	// write with the new checkpoint ID and timestamps.
729	//
730	// sessionIndex is the session slot (0-based), determined by the caller to stay
731	// consistent with the /main ref's session numbering.
732	// This is a no-op if opts.Transcript is empty (and opts.TranscriptPath is unset).
733	func (s *V2GitStore) writeCommittedFullTranscript(ctx context.Context, opts WriteCommittedOptions, sessionIndex int) error {
734		transcript := opts.Transcript
735	
736		// TranscriptPath fallback: data read from disk is an untrusted source,
737		// so we redact it here. The in-memory path (opts.Transcript) is already
738		// pre-redacted by the caller.
739		if transcript.Len() == 0 && opts.TranscriptPath != "" {
740			rawData, readErr := os.ReadFile(opts.TranscriptPath)
741			if readErr != nil {
742				rawData = nil
743			}
744			if len(rawData) > 0 {
745				redacted, redactErr := redact.JSONLBytes(rawData)
746				if redactErr != nil {
747					return fmt.Errorf("failed to redact transcript from file: %w", redactErr)
748				}
749				transcript = redacted
750			}
751		}
752		if transcript.Len() == 0 {
753			return nil // No transcript to write
754		}
755	
756		refName := plumbing.ReferenceName(paths.V2FullCurrentRefName)
757		if err := s.ensureRef(ctx, refName); err != nil {
758			return fmt.Errorf("failed to ensure /full/current ref: %w", err)
759		}
760	
761		parentHash, rootTreeHash, err := s.GetRefState(refName)
762		if err != nil {
763			return err
764		}
765	
766		basePath := opts.CheckpointID.Path() + "/"
767		checkpointPath := opts.CheckpointID.Path()
768		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
769	
770		// Read existing entries at this checkpoint's shard path
771		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
772		if err != nil {
773			return err
774		}
775	
776		// Clear existing entries at this session path before writing new ones
777		for key := range entries {
778			if strings.HasPrefix(key, sessionPath) {
779				delete(entries, key)
780			}
781		}
782	
783		if err := s.writeTranscriptBlobs(ctx, transcript, opts.Agent, nil, sessionPath, entries); err != nil {
784			return err
785		}
786	
787		contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript.Bytes()))
788		if err := s.writeContentHashFromPrecompute(contentHash, nil, sessionPath, entries); err != nil {
789			return err
790		}
791	
792		// Splice checkpoint data into the root tree (preserves other checkpoints' transcripts)
793		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, opts.CheckpointID, basePath, entries)
794		if err != nil {
795			return err
796		}
797	
798		commitMsg := fmt.Sprintf("Checkpoint: %s\n", opts.CheckpointID)
799		if err := s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail); err != nil {
800			return err
801		}
802	
803		s.rotateCurrentIfNeeded(ctx, newTreeHash)
804		return nil
805	}
806	
807	func (s *V2GitStore) rotateCurrentIfNeeded(ctx context.Context, treeHash plumbing.Hash) {
808		checkpointCount, countErr := s.CountCheckpointsInTree(treeHash)
809		if countErr != nil {
810			logging.Warn(ctx, "failed to count checkpoints for rotation check",
811				slog.String("error", countErr.Error()),
812			)
813			return
814		}
815		if checkpointCount < s.maxCheckpoints() {
816			return
817		}
