827	// writeTranscriptBlobs writes pre-redacted, chunked transcript blobs to entries.
828	// When precomputed is non-nil, reuses its chunk blob hashes and skips both
829	// ChunkTranscript and CreateBlobFromContent.
830	func (s *V2GitStore) writeTranscriptBlobs(ctx context.Context, transcript redact.RedactedBytes, agentType types.AgentType, precomputed *PrecomputedTranscriptBlobs, sessionPath string, entries map[string]object.TreeEntry) error {
831		var chunkHashes []plumbing.Hash
832		if precomputed != nil {
833			chunkHashes = precomputed.ChunkHashes
834		} else {
835			chunks, err := chunkTranscript(ctx, transcript.Bytes(), agentType)
836			if err != nil {
837				return fmt.Errorf("failed to chunk transcript: %w", err)
838			}
839			chunkHashes = make([]plumbing.Hash, len(chunks))
840			for i, chunk := range chunks {
841				h, err := CreateBlobFromContent(s.repo, chunk)
842				if err != nil {
843					return err
844				}
845				chunkHashes[i] = h
846			}
847		}
848	
849		for i, blobHash := range chunkHashes {
850			chunkPath := sessionPath + agent.ChunkFileName(paths.V2RawTranscriptFileName, i)
851			entries[chunkPath] = object.TreeEntry{
852				Name: chunkPath,
853				Mode: filemode.Regular,
854				Hash: blobHash,
855			}
856		}
857	
858		return nil
859	}
