861	// writeContentHashFromPrecompute writes the content-hash blob for the given
862	// transcript hash. When precomputed is non-nil, reuses its ContentHashBlob
863	// hash; otherwise creates a fresh blob.
864	func (s *V2GitStore) writeContentHashFromPrecompute(contentHash string, precomputed *PrecomputedTranscriptBlobs, sessionPath string, entries map[string]object.TreeEntry) error {
865		var hashBlob plumbing.Hash
866		if precomputed != nil {
867			hashBlob = precomputed.ContentHashBlob
868		} else {
869			h, err := CreateBlobFromContent(s.repo, []byte(contentHash))
870			if err != nil {
871				return err
872			}
873			hashBlob = h
874		}
875		entries[sessionPath+paths.V2RawTranscriptHashFileName] = object.TreeEntry{
876			Name: sessionPath + paths.V2RawTranscriptHashFileName,
877			Mode: filemode.Regular,
878			Hash: hashBlob,
879		}
880		return nil
881	}
