900	// UpdateSummary persists an AI-generated summary into the latest session's
901	// metadata on the v2 /main ref. Mirrors GitStore.UpdateSummary for v1.
902	func (s *V2GitStore) UpdateSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error {
903		if err := ctx.Err(); err != nil {
904			return err //nolint:wrapcheck // Propagating context cancellation
905		}
906	
907		refName := plumbing.ReferenceName(paths.V2MainRefName)
908		parentHash, rootTreeHash, err := s.GetRefState(refName)
909		if err != nil {
910			return ErrCheckpointNotFound
911		}
912	
913		basePath := checkpointID.Path() + "/"
914		checkpointPath := checkpointID.Path()
915		entries, err := s.gs.flattenCheckpointEntries(rootTreeHash, checkpointPath)
916		if err != nil {
917			return err
918		}
919	
920		rootMetadataPath := basePath + paths.MetadataFileName
921		entry, exists := entries[rootMetadataPath]
922		if !exists {
923			return ErrCheckpointNotFound
924		}
925	
926		cpSummary, err := readJSONFromBlob[CheckpointSummary](s.repo, entry.Hash)
927		if err != nil {
928			return fmt.Errorf("failed to read checkpoint summary: %w", err)
929		}
930		if len(cpSummary.Sessions) == 0 {
931			return ErrCheckpointNotFound
932		}
933	
934		latestIndex := len(cpSummary.Sessions) - 1
935		sessionMetadataPath := fmt.Sprintf("%s%d/%s", basePath, latestIndex, paths.MetadataFileName)
936		sessionEntry, exists := entries[sessionMetadataPath]
937		if !exists {
938			return fmt.Errorf("session metadata not found at index %d", latestIndex)
939		}
940	
941		metadata, err := readJSONFromBlob[CommittedMetadata](s.repo, sessionEntry.Hash)
942		if err != nil {
943			return fmt.Errorf("failed to read session metadata: %w", err)
944		}
945		metadata.Summary = redactSummary(summary)
946	
947		metadataJSON, err := jsonutil.MarshalIndentWithNewline(metadata, "", "  ")
948		if err != nil {
949			return fmt.Errorf("failed to marshal metadata: %w", err)
950		}
951		metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
952		if err != nil {
953			return fmt.Errorf("failed to create metadata blob: %w", err)
954		}
955		entries[sessionMetadataPath] = object.TreeEntry{
956			Name: sessionMetadataPath,
957			Mode: filemode.Regular,
958			Hash: metadataHash,
959		}
960	
961		newTreeHash, err := s.gs.spliceCheckpointSubtree(ctx, rootTreeHash, checkpointID, basePath, entries)
962		if err != nil {
963			return err
964		}
965	
966		authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
967		commitMsg := fmt.Sprintf("Update summary for checkpoint %s (session: %s)", checkpointID, metadata.SessionID)
968		return s.updateRef(ctx, refName, newTreeHash, parentHash, commitMsg, authorName, authorEmail)
969	}
