20	// RepairV2GenerationMetadataResult describes archived v2 generation metadata
21	// repair work performed by RepairV2GenerationMetadata.
22	type RepairV2GenerationMetadataResult struct {
23		Repaired []string
24		Skipped  []string
25		Failed   []string
26		Warnings []string
27	}
28	
29	// RepairV2GenerationMetadata rewrites generation.json for archived v2 /full/*
30	// generation refs using the timestamp envelope from raw transcripts. Remote
31	// archived refs are repaired with force-with-lease when they exist on the
32	// checkpoint remote.
33	//
34	// excludeRefs lists archived /full/<n> refs to skip. Callers that just wrote
35	// a ref with correct generation.json (e.g. the migration packer) pass it here
36	// so the repair pass doesn't re-derive timestamps from those refs'
37	// transcript blobs unnecessarily.
38	func RepairV2GenerationMetadata(ctx context.Context, excludeRefs []plumbing.ReferenceName) (*RepairV2GenerationMetadataResult, error) {
39		repo, err := OpenRepository(ctx)
40		if err != nil {
41			return nil, fmt.Errorf("failed to open git repository: %w", err)
42		}
43	
44		store := checkpoint.NewV2GitStore(repo, "origin")
45		return repairV2GenerationMetadata(ctx, repo, store, excludeRefs)
46	}
47	
48	func repairV2GenerationMetadata(ctx context.Context, repo *git.Repository, store *checkpoint.V2GitStore, excludeRefs []plumbing.ReferenceName) (*RepairV2GenerationMetadataResult, error) {
49		candidates, tempRefs, warnings, err := listArchivedV2GenerationCandidates(ctx, repo, store)
50		if err != nil {
51			return nil, fmt.Errorf("failed to list archived generations: %w", err)
52		}
53		defer removeTempRefs(repo, tempRefs)
54	
55		if len(excludeRefs) > 0 {
56			excluded := make(map[plumbing.ReferenceName]struct{}, len(excludeRefs))
57			for _, refName := range excludeRefs {
58				excluded[refName] = struct{}{}
59			}
60			filtered := candidates[:0]
61			for _, candidate := range candidates {
62				if _, skip := excluded[candidate.RefName]; skip {
63					continue
64				}
65				filtered = append(filtered, candidate)
66			}
67			candidates = filtered
68		}
69	
70		result := &RepairV2GenerationMetadataResult{
71			Warnings: warnings,
72		}
73	
74		pushTarget := &repairPushTarget{}
75	
76		for _, candidate := range candidates {
77			repaired, repairErr := repairOneV2GenerationMetadata(ctx, repo, store, candidate, pushTarget)
78			if repairErr != nil {
79				result.Failed = append(result.Failed, candidate.Name)
80				result.Warnings = append(result.Warnings, fmt.Sprintf("generation %s: %v", candidate.Name, repairErr))
81				continue
82			}
83			if repaired {
84				result.Repaired = append(result.Repaired, candidate.Name)
85			} else {
86				result.Skipped = append(result.Skipped, candidate.Name)
87			}
88		}
89	
90		return result, nil
91	}
92	
93	func repairOneV2GenerationMetadata(
94		ctx context.Context,
95		repo *git.Repository,
96		store *checkpoint.V2GitStore,
97		candidate archivedV2GenerationCandidate,
98		pushTarget *repairPushTarget,
99	) (bool, error) {
100		oldCommitHash, treeHash, refErr := store.GetRefState(candidate.RefName)
101		if refErr != nil {
102			return false, fmt.Errorf("cannot read ref: %w", refErr)
103		}
104	
105		gen, found, timestampErr := store.ComputeGenerationTimestampsFromTrees(treeHash, nil)
106		if timestampErr != nil {
107			return false, fmt.Errorf("failed to compute raw transcript timestamps: %w", timestampErr)
108		}
109		if !found {
110			gen, found, timestampErr = store.ComputeGenerationCheckpointTimestamps(treeHash)
111			if timestampErr != nil {
112				return false, fmt.Errorf("failed to compute checkpoint timestamps: %w", timestampErr)
113			}
114			if !found {
115				return false, nil
116			}
117		}
118	
119		current, genErr := store.ReadGeneration(treeHash)
120		if genErr != nil {
121			return false, fmt.Errorf("failed to read generation.json: %w", genErr)
122		}
123		if generationMetadataEqual(current, gen) {
124			return false, nil
125		}
126	
127		newTreeHash, addErr := store.AddGenerationJSONToTree(treeHash, gen)
128		if addErr != nil {
129			return false, fmt.Errorf("failed to rewrite generation.json: %w", addErr)
130		}
131		if newTreeHash == treeHash {
132			return false, nil
133		}
134	
135		newCommitHash, commitErr := checkpoint.CreateCommit(ctx, repo, newTreeHash, oldCommitHash,
136			fmt.Sprintf("Repair generation metadata: %s\n", candidate.Name),
137			repairAuthorName, repairAuthorEmail)
138		if commitErr != nil {
139			return false, fmt.Errorf("failed to create repair commit: %w", commitErr)
140		}
141	
142		if err := repo.Storer.SetReference(plumbing.NewHashReference(candidate.RefName, newCommitHash)); err != nil {
143			return false, fmt.Errorf("failed to update ref %s: %w", candidate.RefName, err)
144		}
145	
146		if !candidate.HasRemote {
147			return true, nil
148		}
149	
150		target, err := pushTarget.resolve(ctx)
151		if err != nil {
152			rollbackRepairLocalRef(repo, candidate.RefName, oldCommitHash)
153			return false, fmt.Errorf("failed to resolve remote for generation metadata repair push: %w", err)
154		}
155		if target == "" {
156			rollbackRepairLocalRef(repo, candidate.RefName, oldCommitHash)
157			return false, errors.New("no push target available for remote generation metadata repair")
158		}
159	
160		remoteRefName := paths.V2FullRefPrefix + candidate.Name
161		if err := pushRepairedV2Generation(ctx, target, candidate.RefName.String(), remoteRefName, candidate.RefOID); err != nil {
162			rollbackRepairLocalRef(repo, candidate.RefName, oldCommitHash)
163			return false, err
164		}
165		return true, nil
166	}
167	
168	// rollbackRepairLocalRef restores the local ref to its pre-repair commit when
169	// the remote push fails, so local does not silently diverge from origin.
170	func rollbackRepairLocalRef(repo *git.Repository, refName plumbing.ReferenceName, oldCommitHash plumbing.Hash) {
171		_ = repo.Storer.SetReference(plumbing.NewHashReference(refName, oldCommitHash)) //nolint:errcheck // best-effort rollback; the original push error is what we report
172	}
173	
174	// repairPushTarget memoizes the push URL lookup so the remote is resolved at
175	// most once, only when a candidate actually needs to push.
176	type repairPushTarget struct {
177		resolved bool
178		target   string
179		err      error
180	}
181	
182	func (r *repairPushTarget) resolve(ctx context.Context) (string, error) {
183		if r.resolved {
184			return r.target, r.err
185		}
186		r.resolved = true
187		target, _, err := remote.PushURL(ctx, "origin")
188		if err != nil {
189			r.err = fmt.Errorf("push URL: %w", err)
190			return "", r.err
191		}
192		r.target = target
193		return target, nil
194	}
195	
196	func pushRepairedV2Generation(ctx context.Context, target, sourceRef, remoteRef, expectedOID string) error {
197		return pushWithLease(ctx, target, sourceRef+":"+remoteRef, remoteRef, expectedOID,
198			"push repaired generation ref "+remoteRef)
199	}
