201	func generationMetadataEqual(left, right checkpoint.GenerationMetadata) bool {
202		return left.OldestCheckpointAt.Equal(right.OldestCheckpointAt) &&
203			left.NewestCheckpointAt.Equal(right.NewestCheckpointAt)
204	}
